CREATE FUNCTION "auth"."f_0028"() RETURNS TABLE (
  p_0124 uuid,
  f_0041 text,
  c_0199 text[]
) LANGUAGE plpgsql VOLATILE SECURITY DEFINER AS $$
DECLARE
  user_record RECORD;
  cleaned_meta JSONB;
  removed_fields TEXT[];
  template_fields TEXT[];
  field TEXT;
BEGIN
  
  
  IF NOT (
    session_user = '_' OR
    session_user = '_' OR
    COALESCE(current_setting('_', true)::jsonb->>'_', '_') = '_'
  ) THEN
    RAISE EXCEPTION '_';
  END IF;

  
  template_fields := auth.f_0056();

  
  
  PERFORM set_config('_', '_', true);

  BEGIN
    FOR user_record IN
      SELECT u.id, u.f_0041, u.c_0386
      FROM auth.t_0095 u
      WHERE u.c_0386 ?| template_fields
    LOOP
      
      removed_fields := ARRAY[]::TEXT[];
      cleaned_meta := user_record.c_0386;

      FOREACH field IN ARRAY template_fields LOOP
        IF user_record.c_0386 ? field THEN
          removed_fields := removed_fields || field;
          cleaned_meta := cleaned_meta - field;
        END IF;
      END LOOP;

      
      UPDATE auth.t_0095
      SET c_0386 = cleaned_meta
      WHERE id = user_record.id;

      
      p_0124 := user_record.id;
      f_0041 := user_record.f_0041;
      c_0199 := removed_fields;
      RETURN NEXT;
    END LOOP;
  EXCEPTION
    WHEN OTHERS THEN
      
      PERFORM set_config('_', '_', true);
      RAISE;
  END;

  
  PERFORM set_config('_', '_', true);

  RETURN;
END;$$;


CREATE FUNCTION "auth"."f_0037"("p_0003" jsonb) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER AS $$DECLARE
    p_0124 uuid;
    claims jsonb;
    rbac_context jsonb;
    debug_info jsonb := 'null'::jsonb;
BEGIN
    BEGIN
        claims := p_0003->'_';
        debug_info := debug_info || jsonb_build_object('_', true);

        BEGIN
            p_0124 := (claims ->> '_')::uuid;
        EXCEPTION WHEN OTHERS THEN
            p_0124 := NULL;
            debug_info := debug_info || jsonb_build_object('_', true);
        END;

        debug_info := debug_info || jsonb_build_object('_', p_0124);

        IF p_0124 IS NOT NULL THEN
            SELECT public.f_0059(p_0124) INTO rbac_context;

            debug_info := debug_info || jsonb_build_object(
                '_', true,
                '_', rbac_context IS NOT NULL
            );
        END IF;

        IF rbac_context IS NULL THEN
            rbac_context := jsonb_build_object(
                '_', jsonb_build_array(),
                '_', jsonb_build_array(),
                '_', jsonb_build_array(),
                '_', jsonb_build_array(),
                '_', jsonb_build_array(),
                '_', jsonb_build_array(),
                '_', NULL,
                '_', jsonb_build_array()
            );
            debug_info := debug_info || jsonb_build_object('_', true);
        END IF;

        
        claims := jsonb_set(
            claims,
            '_',
            rbac_context,
            true
        );
        
        claims := claims || jsonb_build_object(
            '_', rbac_context,
            '_', debug_info
        );

        p_0003 := jsonb_set(p_0003, '_', claims);

        RETURN p_0003;
    EXCEPTION WHEN OTHERS THEN
        claims := p_0003->'_';
        claims := claims || jsonb_build_object(
            '_', SQLERRM,
            '_', SQLSTATE,
            '_', debug_info
        );
        p_0003 := jsonb_set(p_0003, '_', claims);
        RETURN p_0003;
    END;
END;$$;



