  RETURN NULL;
END;
$$;






CREATE FUNCTION "public"."f_0024"("p_0123" uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE
  has_role BOOLEAN;
  has_verifier_access BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM t_0094 WHERE p_0124 = p_0123
  ) INTO has_role;

  IF has_role THEN
