CREATE FUNCTION "public"."f_0025"("p_0113" uuid, "p_0120" text, "p_0008" text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER AS $$DECLARE
  has_permission BOOLEAN;
BEGIN
  SELECT EXISTS (
