CREATE OR REPLACE VIEW "public"."v_0002" AS
SELECT
    e.id AS p_0001,
    e.name AS c_0171,
    COALESCE(
        json_agg(
            json_build_object(
                '_', u.id,
                '_', u.f_0041,
                '_', r.name,
                '_', u.c_0154
            )
        ) FILTER (WHERE u.id IS NOT NULL),
        'null'::json
    ) AS members,
