    e.c_0481
FROM t_0051 e
LEFT JOIN t_0094 ur ON ur.p_0001 = e.id
LEFT JOIN t_0079 r ON ur.c_0417 = r.id AND r.name = ANY (ARRAY['_'::text, '_'::text])
LEFT JOIN auth.t_0095 u ON ur.p_0124 = u.id
WHERE auth.f_0121()
GROUP BY e.id, e.name, e.c_0088, e.c_0064, e.c_0481;

