CREATE VIEW mrv.v_0010 AS
SELECT
    sps.id,
    sps.c_0425,
    sps.c_0479,
    sps.c_0424,
    sps.c_0295,
    sps.c_0445,
    sps.c_0443,
    sps.c_0500,
    sps.c_0453,
    sps.c_0095,
    f."name" AS field_name
FROM mrv.t_0083 sps
LEFT JOIN LATERAL (
    SELECT f2."name"
    FROM mrv."Polygon" p
    JOIN mrv."t_0012" f2 ON f2."c_0355" = p.id
    WHERE ST_Within(sps.c_0295, p.geometry)
    ORDER BY ST_Area(p.geometry) ASC
    LIMIT 1
) f ON true;



