CREATE OR REPLACE FUNCTION mrv.f_0001()
RETURNS TABLE (
    p_0004 uuid
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_supplier_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (
        auth.f_0066()
        -> '_' -> '_' ->> 0
    )::uuid;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.t_0092 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN QUERY
    SELECT f.id
    FROM mrv."t_0012" f
    WHERE f."c_0172" = v_supplier_id;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0002(
    p_0027 uuid,
    p_0029 text,
    p_0076 uuid,
    p_0033 uuid[]
)
RETURNS TABLE(id uuid, "c_0361" uuid, "c_0183" uuid, "c_0093" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_facility_id uuid;
    v_link_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    BEGIN
        PERFORM p_0029::mrv."ty_0007";
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION '_%_', p_0029;
    END;

    
    IF NOT mrv.f_0114(p_0029, p_0027) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0021"
        WHERE id = p_0076
          AND (
            ("c_0401" = p_0027 AND "c_0402" = p_0029::mrv."ty_0007")
            OR
            ("c_0456" = p_0027 AND "c_0457" = p_0029::mrv."ty_0007")
          )
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF p_0033 IS NULL OR array_length(p_0033, 1) IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_facility_id IN ARRAY p_0033
    LOOP
        
        IF NOT EXISTS (
            SELECT 1 FROM mrv."t_0010"
            WHERE id = v_facility_id
              AND "c_0172" = p_0027
              AND "c_0173" = p_0029::mrv."ty_0007"
        ) THEN
            RAISE EXCEPTION '_%_%_', v_facility_id, p_0027;
        END IF;

        
        IF EXISTS (
            SELECT 1 FROM mrv."t_0022"
            WHERE "c_0361" = p_0076 AND "c_0183" = v_facility_id
        ) THEN
            CONTINUE;
        END IF;

        
        INSERT INTO mrv."t_0022" (id, "c_0361", "c_0183", "c_0093")
        VALUES (gen_random_uuid(), p_0076, v_facility_id, NOW())
        RETURNING id INTO v_link_id;

        RETURN QUERY SELECT pf.id, pf."c_0361", pf."c_0183", pf."c_0093"
                     FROM mrv."t_0022" pf WHERE pf.id = v_link_id;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0014(
    p_0032 uuid,
    p_0038 uuid[]
)
RETURNS TABLE(id uuid, "c_0183" uuid, "c_0192" uuid, "c_0020" timestamp, "c_0021" uuid, "c_0093" timestamptz, "c_0528" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_facility_entity_type text;
    v_facility_entity_id uuid;
    v_farmer_id uuid;
    v_result_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    SELECT "c_0173"::text, "c_0172"
    INTO v_facility_entity_type, v_facility_entity_id
    FROM mrv."t_0010"
    WHERE id = p_0032;

    IF v_facility_entity_type IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF NOT mrv.f_0114(v_facility_entity_type, v_facility_entity_id) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF p_0038 IS NULL OR array_length(p_0038, 1) IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_farmer_id IN ARRAY p_0038
    LOOP
        INSERT INTO mrv."t_0011" (id, "c_0183", "c_0192", "c_0020", "c_0021", "c_0093", "c_0528")
        VALUES (gen_random_uuid(), p_0032, v_farmer_id, NOW(), v_current_user_id, NOW(), NOW())
        ON CONFLICT ("c_0183", "c_0192")
        DO UPDATE SET "c_0021" = v_current_user_id, "c_0528" = NOW()
        RETURNING id INTO v_result_id;

        RETURN QUERY SELECT ff.id, ff."c_0183", ff."c_0192", ff."c_0020",
                            ff."c_0021", ff."c_0093", ff."c_0528"
                     FROM mrv."t_0011" ff WHERE ff.id = v_result_id;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0015(
    p_0076 uuid,
    p_0114 uuid[]
)
RETURNS TABLE (
    id uuid,
    c_0364 uuid,
    p_0005 uuid,
    c_0022 timestamptz,
    c_0023 uuid,
    c_0095 timestamptz,
    c_0529 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_reporting_entity_id uuid;
    v_reporting_entity_type text;
    v_current_user_id uuid;
    v_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT p."c_0401", p."c_0402"::text
    INTO v_reporting_entity_id, v_reporting_entity_type
    FROM mrv."t_0021" p
    WHERE p.id = p_0076;

    IF v_reporting_entity_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0124(v_reporting_entity_id, v_reporting_entity_type) THEN
        RAISE EXCEPTION '_';
    END IF;

    FOREACH v_user_id IN ARRAY p_0114
    LOOP
        RETURN QUERY
        INSERT INTO mrv."t_0023" (
            "c_0361", "c_0192", "c_0021", "c_0020", "c_0093", "c_0528"
        ) VALUES (
            p_0076, v_user_id, v_current_user_id, NOW(), NOW(), NOW()
        )
        ON CONFLICT ("c_0361", "c_0192")
        DO UPDATE SET
            "c_0021" = EXCLUDED."c_0021",
            "c_0528" = NOW()
        RETURNING
            "t_0023".id,
            "t_0023"."c_0361",
            "t_0023"."c_0192",
            "t_0023"."c_0020",
            "t_0023"."c_0021",
            "t_0023"."c_0093",
            "t_0023"."c_0528";
    END LOOP;
END;
$$;




CREATE OR REPLACE FUNCTION mrv.f_0016(
    p_0036 uuid[],
    p_0118 int
)
RETURNS TABLE (
    p_0004 uuid,
    c_0060 double precision,
    c_0056 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF array_length(p_0036, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH dom_results AS (
        SELECT DISTINCT ON (dcr."c_0187")
            dcr."c_0187" AS p_0004,
            dcr."c_0321" / 1000.0 AS c_0060,
            dcr."c_0055" AS c_0056
        FROM mrv."t_0007" dcr
        WHERE dcr."c_0187" = ANY(p_0036)
            AND dcr."c_0057" = p_0118
            AND dcr."c_0321" > 0
        ORDER BY dcr."c_0187", dcr."c_0052" DESC
    ),
    soil_metrics AS (
        SELECT DISTINCT ON (fsm."c_0187")
            fsm."c_0187" AS p_0004,
            fsm.value AS c_0060,
            NULL::jsonb AS c_0056
        FROM mrv."t_0013" fsm
        WHERE fsm."c_0187" = ANY(p_0036)
            AND fsm."c_0357" = 'v1'
            AND fsm."c_0470" <= make_date(p_0118, 12, 31)
            AND fsm."c_0168" >= make_date(p_0118, 1, 1)
            AND fsm.value > 0
        ORDER BY fsm."c_0187", fsm."c_0470" DESC, fsm."c_0168" DESC
    ),
    all_farms AS (
        SELECT unnest(p_0036) AS p_0004
    )
    SELECT
        af.p_0004,
        COALESCE(dr.c_0060, sm.c_0060, 0.0)::double precision,
        COALESCE(dr.c_0056, sm.c_0056)
    FROM all_farms af
    LEFT JOIN dom_results dr ON dr.p_0004 = af.p_0004
    LEFT JOIN soil_metrics sm ON sm.p_0004 = af.p_0004 AND dr.p_0004 IS NULL;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0017(
    p_0073 uuid
)
RETURNS TABLE (
    id uuid,
    con_0122 uuid,
    c_0273 uuid,
    c_0472 text,
    c_0219 text,
    c_0497 int,
    c_0498 double precision,
    c_0127 double precision,
    c_0037 boolean[],
    c_0264 boolean,
    c_0124 boolean[],
    c_0266 boolean,
    c_0126 double precision,
    c_0265 boolean,
    c_0125 double precision,
    c_0267 boolean,
    c_0210 boolean[],
    c_0269 boolean,
    c_0212 double precision,
    c_0268 boolean,
    c_0211 double precision,
    c_0176 text,
    c_0413 jsonb,
    c_0190 uuid[],
    c_0095 timestamptz,
    c_0529 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_supplier_id uuid;
    v_plan RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0073 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (
        auth.f_0066()
        -> '_' -> '_' ->> 0
    )::uuid;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM public.t_0092 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT cp.*
    INTO v_plan
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0172" = v_supplier_id;

    IF v_plan IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_plan.c_0472 = 'v1' THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_plan.c_0472 = 'v1' THEN
        RETURN QUERY SELECT
            v_plan.id,
            v_plan."c_0172",
            v_plan."c_0272",
            v_plan.c_0472::text,
            v_plan."c_0218"::text,
            v_plan."c_0494",
            v_plan."c_0495",
            v_plan."c_0121",
            v_plan."c_0036",
            v_plan."c_0251",
            v_plan."c_0118",
            v_plan."c_0253",
            v_plan."c_0120",
            v_plan."c_0252",
            v_plan."c_0119",
            v_plan."c_0254",
            v_plan."c_0206",
            v_plan."c_0256",
            v_plan."c_0208",
            v_plan."c_0255",
            v_plan."c_0207",
            v_plan."c_0175",
            v_plan.c_0413,
            ARRAY(SELECT cpf."c_0187" FROM mrv."t_0002" cpf WHERE cpf."c_0058" = v_plan.id AND cpf."c_0187" IS NOT NULL),
            v_plan."c_0093",
            v_plan."c_0528";
        RETURN;
    END IF;

    UPDATE mrv."t_0001"
    SET c_0472 = 'v1',
        "c_0175" = NULL,
        "c_0528" = NOW()
    WHERE mrv."t_0001".id = p_0073
      AND mrv."t_0001"."c_0172" = v_supplier_id;

    RETURN QUERY SELECT
        cp.id,
        cp."c_0172",
        cp."c_0272",
        cp.c_0472::text,
        cp."c_0218"::text,
        cp."c_0494",
        cp."c_0495",
        cp."c_0121",
        cp."c_0036",
        cp."c_0251",
        cp."c_0118",
        cp."c_0253",
        cp."c_0120",
        cp."c_0252",
        cp."c_0119",
        cp."c_0254",
        cp."c_0206",
        cp."c_0256",
        cp."c_0208",
        cp."c_0255",
        cp."c_0207",
        cp."c_0175",
        cp.c_0413,
        ARRAY(SELECT cpf."c_0187" FROM mrv."t_0002" cpf WHERE cpf."c_0058" = cp.id AND cpf."c_0187" IS NOT NULL),
        cp."c_0093",
        cp."c_0528"
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0172" = v_supplier_id;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0027()
RETURNS integer
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, public
AS $$
DECLARE
    deleted_count integer;
BEGIN
    DELETE FROM mrv.t_0073
    WHERE c_0095 < now() - INTERVAL '1 day';

    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0029(
    p_0105 uuid,
    p_0048 text,
