    c_0269 boolean,
    c_0212 double precision,
    c_0268 boolean,
    c_0211 double precision,
    c_0213 text,
    c_0176 text,
    c_0413 jsonb,
    c_0190 uuid[],
    c_0095 timestamptz,
    c_0529 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_plan_id uuid;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0105 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.t_0092 s
        WHERE s.id = p_0105
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0036 IS NOT NULL AND array_length(p_0036, 1) > 0 THEN
        IF EXISTS (
            SELECT 1 FROM unnest(p_0036) AS requested_id
            WHERE NOT EXISTS (
                SELECT 1 FROM mrv."t_0012" f
                WHERE f.id = requested_id
                  AND f."c_0172" = p_0105
            )
        ) THEN
