        "c_0272",
        "c_0472",
        "c_0218",
        "c_0494",
        "c_0495",
        "c_0121",
        "c_0036",
        "c_0251",
        "c_0118",
        "c_0253",
        "c_0120",
        "c_0252",
        "c_0119",
        "c_0122",
        "c_0254",
        "c_0206",
        "c_0256",
        "c_0208",
        "c_0255",
        "c_0207",
        "c_0209",
        "c_0175",
        "c_0413"
    ) VALUES (
        p_0105,
        p_0067,
        NULL,
        'v1'::mrv."ty_0002",
        p_0048::mrv."ty_0001",
        p_0109,
        p_0110,
        p_0021,
        p_0011,
        p_0057,
        p_0018,
        p_0059,
        p_0020,
        p_0058,
