        p_0022::mrv."ty_0019",
        p_0060,
        p_0043,
        p_0062,
        p_0045,
        p_0061,
        p_0044,
        p_0046::mrv."ty_0019",
        NULL,
        NULL
    )
    RETURNING mrv."t_0001".id INTO v_plan_id;

    IF p_0036 IS NOT NULL AND array_length(p_0036, 1) > 0 THEN
        INSERT INTO mrv."t_0002" ("c_0058", "c_0187")
        SELECT v_plan_id, unnest(p_0036)
        ON CONFLICT ("c_0058", "c_0187") DO NOTHING;
    END IF;

    RETURN QUERY
    SELECT
        cp.id,
        cp."c_0172",
        cp.c_0294,
        cp."c_0328",
        cp."c_0272",
        cp.c_0472::text,
        cp."c_0218"::text,
        cp."c_0494",
        cp."c_0495",
        cp."c_0121",
        cp."c_0036",
        cp."c_0251",
        cp."c_0118",
        cp."c_0253",
        cp."c_0120",
        cp."c_0252",
        cp."c_0119",
        cp."c_0122"::text,
        cp."c_0254",
        cp."c_0206",
        cp."c_0256",
        cp."c_0208",
        cp."c_0255",
        cp."c_0207",
        cp."c_0209"::text,
        cp."c_0175",
        cp.c_0413,
        ARRAY(SELECT cpf."c_0187" FROM mrv."t_0002" cpf WHERE cpf."c_0058" = cp.id AND cpf."c_0187" IS NOT NULL),
        cp."c_0093",
        cp."c_0528"
    FROM mrv."t_0001" cp
    WHERE cp.id = v_plan_id;
END;
$$;

