    IF NOT EXISTS (
        SELECT 1
        FROM public.t_0092 s
        WHERE s.id = v_supplier_id
          AND s.ty_0034 = 'v1'
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN QUERY
    SELECT
        cp.id,
        cp."c_0172",
        cp.c_0294,
        cp."c_0328",
        cp."c_0272",
        cp.c_0472::text,
        cp."c_0218"::text,
