        cp."c_0255",
        cp."c_0207",
        cp."c_0209"::text,
        cp."c_0175",
        cp.c_0413,
        ARRAY(
            SELECT cpf."c_0187"
            FROM mrv."t_0002" cpf
            WHERE cpf."c_0058" = cp.id
              AND cpf."c_0187" IS NOT NULL
        ),
        cp."c_0093",
        cp."c_0528",
        (
            SELECT jsonb_agg(jsonb_build_object(
                '_', f.id,
                '_', f.name,
                '_', CASE WHEN f."c_0355" IS NOT NULL THEN (
                    SELECT ST_Area(p.geometry::geography) / 10000.0
                    FROM mrv."Polygon" p
                    WHERE p.id = f."c_0355"
                ) END,
                '_', (
                    SELECT c."c_0102"::text
                    FROM mrv."t_0006" c
                    WHERE c."c_0187" = f.id
