            ) ORDER BY f.id)
            FROM mrv."t_0002" cpf2
            JOIN mrv."t_0012" f ON f.id = cpf2."c_0187"
            WHERE cpf2."c_0058" = cp.id
        )
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073
      AND cp."c_0172" = v_supplier_id;
END;
$$;

