CREATE OR REPLACE FUNCTION mrv.f_0058(
    p_0051 text,
    p_0083 text,
    p_0088 float8 DEFAULT 1
)
RETURNS TABLE (
    c_0430 float8,
    c_0432 float8,
    c_0433 float8
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    SELECT
        ief."c_0430" * COALESCE(p_0088, 1),
        ief."c_0432" * COALESCE(p_0088, 1),
        ief."c_0433" * COALESCE(p_0088, 1)
    FROM mrv."t_0017" ief
    WHERE ief."c_0234" = p_0051
      AND ief."c_0396" = p_0083;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_%_', p_0051, p_0083;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0060(
    p_0116 uuid,
    p_0026 uuid,
    p_0031 int
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_expires_at timestamptz;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0026 => p_0026) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0031 < 1 OR p_0031 > 365 THEN
        RAISE EXCEPTION '_%_', p_0031;
    END IF;

    v_expires_at := now() + make_interval(days => p_0031);

    UPDATE public.t_0096
    SET c_0415 = clock_timestamp(), c_0416 = v_current_user_id
    WHERE c_0537 = p_0116
      AND p_0001 = p_0026
      AND c_0415 IS NULL;

    INSERT INTO public.t_0096 (c_0537, p_0001, c_0221, c_0220, c_0181)
    VALUES (p_0116, p_0026, v_current_user_id, clock_timestamp(), v_expires_at);

    
    INSERT INTO audit.t_0097 (c_0537, p_0001, action, c_0141)
    VALUES (
        p_0116,
        p_0026,
        '_',
        jsonb_build_object(
            '_', v_current_user_id,
            '_', v_expires_at,
            '_', p_0031
        )
    );
END;
$$;



CREATE OR REPLACE FUNCTION mrv.f_0068()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_type text;
    v_farm_id uuid;
    v_date timestamp(3);
    v_fk_column text;
BEGIN
    CASE TG_TABLE_NAME
        WHEN '_' THEN
            v_type := '_';
            v_date := NEW."c_0017";
            v_farm_id := (SELECT c."c_0187" FROM mrv."t_0006" c WHERE c.id = NEW."c_0117");
            v_fk_column := '_';
        WHEN '_' THEN
            v_type := '_';
            v_date := NEW."c_0222";
            v_farm_id := (SELECT c."c_0187" FROM mrv."t_0006" c WHERE c.id = NEW."c_0117");
            v_fk_column := '_';
        WHEN '_' THEN
            v_type := '_';
            v_date := NEW."c_0422";
            v_farm_id := NEW."c_0187";
            v_fk_column := '_';
        WHEN '_' THEN
            v_type := '_';
            v_date := NEW."c_0483";
            v_farm_id := NEW."c_0187";
            v_fk_column := '_';
        ELSE
            RAISE EXCEPTION '_%_', TG_TABLE_NAME;
    END CASE;

    IF v_farm_id IS NULL THEN
        RAISE EXCEPTION '_%_%_', TG_TABLE_NAME, NEW.id;
    END IF;

    EXECUTE format(
        '_%_',
        v_fk_column
    ) USING v_type, v_date, 'null'::jsonb, v_farm_id, NEW.id;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0069(p_0093 UUID)
RETURNS TABLE (
  c_0520 INT,
  c_0513    INT,
  c_0029    INT,
  c_0540    INT,
  c_0527 INT,
  c_0182    INT
)
LANGUAGE plpgsql
VOLATILE
SET search_path = mrv, public
AS $$
DECLARE
  v_threshold_auto_meters CONSTANT FLOAT := 50.0;
  v_threshold_warn_meters CONSTANT FLOAT := 500.0;
BEGIN
  
  
  
  UPDATE mrv.t_0082
  SET
    c_0303         = '_',
    c_0304 = NULL,
    c_0302     = NULL
  WHERE c_0425 = p_0093
    AND c_0303 <> '_';

  
  
  
  
  
  
  
  
  
  
  
  
  
  
  UPDATE mrv.t_0082 AS actual
  SET
    c_0303         = winner.c_0303,
    c_0304 = winner.suggested_id,
    c_0302     = winner.distance_m
  FROM (
    
    SELECT DISTINCT ON (nearest.suggested_id)
      nearest.actual_id,
      nearest.suggested_id,
      nearest.distance_m,
      CASE
        WHEN nearest.distance_m <= v_threshold_auto_meters THEN '_'
        ELSE '_'
      END AS c_0303
    FROM (
      
      
      SELECT DISTINCT ON (a.id)
        a.id                                                       AS actual_id,
        s.id                                                       AS suggested_id,
        ST_Distance(a.c_0295::geography, s.c_0295::geography)  AS distance_m
      FROM mrv.t_0082 a
      JOIN mrv.t_0085 st_actual
        ON st_actual.c_0425 = p_0093
        AND ST_Within(a.c_0295, st_actual.geometry)
      JOIN mrv.t_0083 s
        ON s.c_0425 = p_0093
        AND s.c_0479 = st_actual.id
      WHERE a.c_0425 = p_0093
        AND a.c_0303 <> '_'
        AND ST_Distance(a.c_0295::geography, s.c_0295::geography) <= v_threshold_warn_meters
        AND NOT EXISTS (
          SELECT 1
          FROM mrv.t_0082 manual
          WHERE manual.c_0425 = p_0093
            AND manual.c_0303 = '_'
            AND manual.c_0304 = s.id
        )
      ORDER BY a.id, ST_Distance(a.c_0295::geography, s.c_0295::geography), s.id
    ) AS nearest
    ORDER BY nearest.suggested_id, nearest.distance_m, nearest.actual_id
  ) AS winner
  WHERE winner.actual_id = actual.id;

  
  RETURN QUERY
  SELECT
    (SELECT COUNT(*)::INT FROM mrv.t_0083   WHERE c_0425 = p_0093),
    (SELECT COUNT(*)::INT FROM mrv.t_0082      WHERE c_0425 = p_0093),
    (SELECT COUNT(*)::INT FROM mrv.t_0082      WHERE c_0425 = p_0093 AND c_0303 IN ('_', '_')),
    (SELECT COUNT(*)::INT FROM mrv.t_0082      WHERE c_0425 = p_0093 AND c_0303 = '_'),
    (
      
      SELECT COUNT(*)::INT
      FROM mrv.t_0083 sug
      WHERE sug.c_0425 = p_0093
        AND NOT EXISTS (
          SELECT 1
          FROM mrv.t_0082 act
          WHERE act.c_0304 = sug.id
        )
    ),
    (
      
      SELECT COUNT(*)::INT
      FROM mrv.t_0082
      WHERE c_0425 = p_0093
        AND c_0303 = '_'
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0072(
    p_0095 text,
    p_0027 uuid DEFAULT NULL
)
RETURNS TABLE (
    c_0090 text,
    c_0195 int,
    c_0496 int
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    WITH farm_counts AS (
        SELECT
            f."ty_0003"::text AS c_0090,
            COUNT(f.id)::int AS c_0189
        FROM mrv."t_0012" f
        WHERE f."ty_0003" IS NOT NULL
            AND (p_0027 IS NULL OR f."c_0172" = p_0027)
            AND (p_0095 IS NULL OR f."ty_0016"::text = p_0095)
        GROUP BY f."ty_0003"
    ),
    crop_counts AS (
        SELECT
            f."ty_0003"::text AS c_0090,
            COUNT(DISTINCT c."c_0102")::int AS crop_count
        FROM mrv."t_0012" f
        LEFT JOIN mrv."t_0006" c ON c."c_0187" = f.id
        WHERE f."ty_0003" IS NOT NULL
            AND (p_0027 IS NULL OR f."c_0172" = p_0027)
            AND (p_0095 IS NULL OR f."ty_0016"::text = p_0095)
        GROUP BY f."ty_0003"
    )
    SELECT
        fc.c_0090,
        fc.c_0189,
        COALESCE(cc.crop_count, 0)
    FROM farm_counts fc
    LEFT JOIN crop_counts cc ON cc.c_0090 = fc.c_0090;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0074(
    p_0066 float8,
    p_0068 float8,
    p_0081 float8
)
RETURNS TABLE (
    id uuid,
    p_0004 uuid,
    geometry text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_user_id uuid;
    v_rbac jsonb;
    v_entity_ids uuid[];
BEGIN
    v_user_id := auth.f_0102();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_rbac := auth.f_0066()->'_';

    v_entity_ids := ARRAY[v_user_id];
    IF v_rbac IS NOT NULL THEN
        v_entity_ids := v_entity_ids || ARRAY(
            SELECT x::uuid FROM jsonb_array_elements_text(
                COALESCE(v_rbac->'_', 'null'::jsonb) ||
                COALESCE(v_rbac->'_', 'null'::jsonb) ||
                COALESCE(v_rbac->'_', 'null'::jsonb)
            ) x
            WHERE x IS NOT NULL AND x <> '_'
        );
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p."c_0187" AS p_0004,
        ST_AsGeoJSON(p.geometry)::text AS geometry
    FROM mrv."Polygon" p
    LEFT JOIN mrv."t_0012" f ON f.id = p."c_0187"
    WHERE ST_DWithin(
        p.geometry::geography,
        ST_SetSRID(ST_MakePoint(p_0068, p_0066), 4326)::geography,
        p_0081
    )
    AND (
        auth.f_0062()
        OR p."c_0187" IS NULL
        OR f."c_0172" = ANY(v_entity_ids)
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0075(
    p_0026 uuid,
    p_0118 int
)
RETURNS TABLE (
    c_0516 int,
    c_0514 numeric,
    c_0091 int,
    c_0092 numeric,
    c_0502 jsonb,
    c_0106 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0026 => p_0026) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0118 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0118 < 2000 OR p_0118 > EXTRACT(YEAR FROM NOW())::int + 5 THEN
        RAISE EXCEPTION '_%_', p_0118;
    END IF;

    RETURN QUERY
    WITH enterprise_farms AS (
        
        SELECT f.id AS p_0004, f."c_0355"
        FROM mrv."t_0012" f
        JOIN public.t_0050 es ON es.p_0122 = f."c_0172"
        WHERE es.p_0001 = p_0026
        UNION
        
        SELECT f.id AS p_0004, f."c_0355"
        FROM mrv."t_0012" f
        JOIN public.t_0091 sf ON sf.p_0005 = f."c_0172"
        JOIN public.t_0050 es ON es.p_0122 = sf.p_0122
        WHERE es.p_0001 = p_0026
    ),
    year_cultivations AS (
        SELECT
            c.id AS cultivation_id,
            c."c_0187",
            c."c_0102"::text AS c_0105,
            c."c_0250",
            c."c_0501"::text AS c_0503
        FROM mrv."t_0006" c
        JOIN enterprise_farms ef ON ef.p_0004 = c."c_0187"
        WHERE c."c_0351" >= make_date(p_0118, 1, 1)
          AND c."c_0351" < make_date(p_0118 + 1, 1, 1)
    ),
    farms_with_cultivations AS (
        SELECT DISTINCT "c_0187" FROM year_cultivations
    ),
    farm_areas AS (
        SELECT
            ef.p_0004,
            ST_Area(p.geometry::geography) / 10000 AS c_0018
        FROM enterprise_farms ef
        JOIN mrv."Polygon" p ON p.id = ef."c_0355"
        WHERE ef.p_0004 IN (SELECT "c_0187" FROM farms_with_cultivations)
    ),
    counts AS (
        SELECT
            COUNT(DISTINCT "c_0187")::int                                    AS c_0516,
            COUNT(*) FILTER (WHERE "c_0250" = true)::int               AS c_0091,
            COUNT(*)::int                                                     AS total_cultivations,
            COUNT(*) FILTER (WHERE c_0503 = '_')::int      AS till_conventional,
            COUNT(*) FILTER (WHERE c_0503 = '_')::int           AS till_reduced,
            COUNT(*) FILTER (WHERE c_0503 = '_')::int           AS till_no_till,
            COUNT(*) FILTER (WHERE c_0503 IS NULL)::int               AS till_unknown
        FROM year_cultivations
    ),
    crop_counts AS (
        SELECT c_0105, COUNT(*)::int AS cnt
        FROM year_cultivations
        GROUP BY c_0105
    )
    SELECT
        c.c_0516,
        COALESCE((SELECT SUM(c_0018) FROM farm_areas), 0)::numeric        AS c_0514,
        c.c_0091,
        CASE
            WHEN c.total_cultivations = 0 THEN 0
            ELSE (c.c_0091::numeric / c.total_cultivations::numeric)
        END                                                                  AS c_0092,
        jsonb_build_object(
            '_', c.till_conventional,
            '_',      c.till_reduced,
            '_',      c.till_no_till,
            '_',      c.till_unknown
        )                                                                    AS c_0502,
        COALESCE(
            (SELECT jsonb_object_agg(c_0105, cnt) FROM crop_counts),
            'null'::jsonb
        )                                                                    AS c_0106
    FROM counts c;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0079(p_0078 UUID)
RETURNS TABLE (
    id                     UUID,
    c_0296       TEXT,
    c_0071        DATE,
    c_0444            DOUBLE PRECISION,
    c_0048     DOUBLE PRECISION,
    c_0065           DOUBLE PRECISION,
    c_0423        DOUBLE PRECISION,
    c_0466      UUID,
    c_0467    TEXT
)
LANGUAGE plpgsql
STABLE
SET search_path = mrv, public
AS $$
DECLARE
    v_project_geometry public.geometry;
BEGIN
    
    
    
    SELECT ST_Union(s.geometry)
    INTO v_project_geometry
    FROM mrv.t_0085 s
    WHERE s.c_0425 = p_0078
      AND s.geometry IS NOT NULL;

    IF v_project_geometry IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        a.id,
        ST_AsGeoJSON(a.c_0295)::TEXT  AS c_0296,
        a.c_0071,
        a.c_0444,
        a.c_0048,
        a.c_0065,
        a.c_0423,
        p.id                            AS c_0466,
        p.name                          AS c_0467
    FROM mrv.t_0082 a
    JOIN mrv.t_0084 p ON p.id = a.c_0425
    WHERE a.c_0425 <> p_0078
      AND a.c_0071 IS NOT NULL
      AND ST_Within(a.c_0295, v_project_geometry)
    ORDER BY a.c_0095 DESC;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0080(
    p_0084 uuid,
    p_0085 text,
    p_0098 uuid,
    p_0099 text
)
RETURNS TABLE (
    id uuid,
    c_0090 text,
    c_0105 text,
    c_0362 float8,
    c_0193 int
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    WITH country_crop_pairs AS (
        SELECT
            p."c_0089"::text,
            p."c_0102"::text,
            MIN(p.id::text)::uuid AS id
        FROM mrv."t_0021" p
        WHERE p."c_0401" = p_0084
            AND p."c_0402"::text = p_0085
            AND p."c_0456" = p_0098
            AND p."c_0457"::text = p_0099
            AND p."c_0089" IS NOT NULL
            AND p."c_0102" IS NOT NULL
        GROUP BY p."c_0089", p."c_0102"
    )
    SELECT
        ccp.id,
        ccp."c_0089",
        ccp."c_0102",
        COALESCE(SUM(fp."c_0359"), 0)::float8 AS "c_0359",
        COUNT(DISTINCT fp."c_0456")::int AS "farmerCount"
    FROM country_crop_pairs ccp
    
    
    LEFT JOIN mrv."t_0021" fp ON
        fp."c_0089"::text = ccp."c_0089"
        AND fp."c_0102"::text = ccp."c_0102"
        AND fp."c_0401" = p_0098
        AND fp."c_0402" = 'v1'
        AND fp."c_0457" = 'v1'
        AND fp."c_0456" IS NOT NULL
    GROUP BY ccp.id, ccp."c_0089", ccp."c_0102";
END;
$$;



CREATE OR REPLACE FUNCTION mrv.f_0081(
    p_0076 uuid
)
RETURNS TABLE (
    c_0364 uuid,
    c_0059 double precision,
    p_0004 uuid,
    c_0191 text,
    c_0188 double precision,
    f_0048 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_source_entity_type text;
    v_source_entity_id uuid;
    v_procurement_amount double precision;
    v_procurement_date date;
    v_crop_type text;
    v_procurement_year int;
    v_farmer_total_yield double precision;
    v_proportion double precision;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT p."c_0457", p."c_0456", p."c_0359",
           p."c_0360", p."c_0102"
    INTO v_source_entity_type, v_source_entity_id, v_procurement_amount,
         v_procurement_date, v_crop_type
    FROM mrv."t_0021" p
    WHERE p.id = p_0076
        AND (
            auth.f_0119(p_0105 => p."c_0401")
            OR EXISTS (
                SELECT 1
                FROM public.t_0050 es
                WHERE es.p_0122 = p."c_0401"
                    AND auth.f_0119(p_0026 => es.p_0001)
            )
        );

    IF NOT FOUND THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_source_entity_type <> '_' THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_procurement_amount IS NULL OR v_procurement_amount = 0 THEN
        RETURN;
    END IF;

    IF v_procurement_date IS NULL THEN
        RAISE EXCEPTION '_%_', p_0076;
    END IF;

    v_procurement_year := EXTRACT(YEAR FROM v_procurement_date)::int;

    SELECT COALESCE(SUM(hr."c_0512"), 0) INTO v_farmer_total_yield
    FROM mrv."t_0016" hr
    JOIN mrv."t_0006" c ON c.id = hr."c_0117"
    JOIN mrv."t_0012" f ON f.id = c."c_0187"
    WHERE f."c_0172" = v_source_entity_id
        AND c."c_0102"::text = v_crop_type
        AND c.c_0472 = 'v1'
        AND c."c_0222" >= make_date(v_procurement_year, 1, 1)
        AND c."c_0222" <= make_date(v_procurement_year, 12, 31);

    IF v_farmer_total_yield = 0 THEN
        RETURN;
    END IF;

    v_proportion := LEAST(v_procurement_amount / v_farmer_total_yield, 1.0);

    RETURN QUERY
    WITH c_0190 AS (
        SELECT f.id AS fid, f.name AS fname
        FROM mrv."t_0012" f
        WHERE f."c_0172" = v_source_entity_id
    ),
    carbon_data AS (
        SELECT bcd.p_0004, bcd.c_0060, bcd.c_0056
        FROM mrv.f_0016(
            ARRAY(SELECT fid FROM c_0190),
            v_procurement_year
        ) bcd
        WHERE bcd.c_0060 > 0
    )
    SELECT
        p_0076,
        SUM(v_proportion * cd.c_0060) OVER () AS c_0059,
        fi.fid AS p_0004,
        fi.fname AS c_0191,
        (v_proportion * cd.c_0060)::double precision AS c_0188,
        cd.c_0056 AS f_0048
    FROM c_0190 fi
    JOIN carbon_data cd ON cd.p_0004 = fi.fid;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0083(
    p_0035 uuid
)
RETURNS TABLE (
    id uuid,
    name text,
    c_0356 uuid
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_farm RECORD;
    v_polygon RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0035 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT f.id, f."name", f."c_0355", f."c_0172"
    INTO v_farm
    FROM mrv."t_0012" f
    WHERE f.id = p_0035;

    IF v_farm IS NULL THEN
        RAISE EXCEPTION '_%_', p_0035;
    END IF;

    IF NOT (
        auth.f_0119(p_0026 => v_farm."c_0172")
        OR auth.f_0119(p_0105 => v_farm."c_0172")
        OR auth.f_0119(p_0037 => v_farm."c_0172")
    ) THEN
        RAISE EXCEPTION '_%_', p_0035;
    END IF;

    DELETE FROM mrv."t_0012" WHERE mrv."t_0012".id = p_0035;

    SELECT p."c_0460"
    INTO v_polygon
    FROM mrv."Polygon" p
    WHERE p.id = v_farm."c_0355";

    
    
    
    IF FOUND AND v_polygon."c_0460" IS NULL THEN
        
        
        
        
        DELETE FROM mrv."Polygon" WHERE mrv."Polygon".id = v_farm."c_0355";
    END IF;

    RETURN QUERY SELECT
        v_farm.id,
        v_farm."name",
        v_farm."c_0355";
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0084(
    p_0027 uuid,
    p_0040 uuid
)
RETURNS boolean
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT (
        auth.f_0119(p_0026 => p_0027)
        OR auth.f_0119(p_0105 => p_0027)
        OR auth.f_0119(p_0037 => p_0027)
    ) THEN
        RAISE EXCEPTION '_%_', p_0027;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0014" fa
        JOIN mrv."t_0006" c ON c.id = fa."c_0117"
        JOIN mrv."t_0012" f ON f.id = c."c_0187"
        WHERE fa.id = p_0040 AND f."c_0172" = p_0027
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    DELETE FROM mrv."t_0014" WHERE id = p_0040;
    RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0089(
    p_0050 uuid,
    p_0026 uuid,
    p_0080 float8,
    p_0107 date
)
RETURNS TABLE(id uuid, "c_0486" uuid, "c_0170" uuid, "c_0455" text, "c_0458" uuid, "c_0102" text, "c_0381" double precision, "c_0489" date, "c_0094" uuid, "c_0093" timestamptz, "c_0528" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_existing RECORD;
    v_farm RECORD;
    v_available float8 := 0;
    v_already_supplied float8;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    PERFORM pg_advisory_xact_lock(hashtext('_' || p_0050::text));

    SELECT id, "c_0486", "c_0170", "c_0455", "c_0458", "c_0102"
    INTO v_existing
    FROM mrv."t_0028"
    WHERE id = p_0050;

    IF v_existing IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0105 => v_existing."c_0486") THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0080 <= 0 OR p_0080 > 1000000 THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0021"
        WHERE "c_0401" = v_existing."c_0486"
          AND "c_0402" = 'v1'
          AND "c_0170" = p_0026
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_existing."c_0455"::text = '_' THEN
        SELECT id, "c_0172"
        INTO v_farm
        FROM mrv."t_0012"
        WHERE id = v_existing."c_0458"
        LIMIT 1;

        IF v_farm IS NULL OR v_farm."c_0172" != v_existing."c_0486" THEN
            RAISE EXCEPTION '_%_%_',
                v_existing."c_0458", v_existing."c_0486";
        END IF;

        SELECT COALESCE(SUM(hr."c_0512"), 0)
        INTO v_available
        FROM mrv."t_0016" hr
        JOIN mrv."t_0006" c ON c.id = hr."c_0117"
        WHERE c."c_0102"::text = v_existing."c_0102"::text
          AND c.c_0472 = 'v1'
          AND c."c_0187" = v_farm.id;

    ELSIF v_existing."c_0455"::text = '_' THEN
        SELECT COALESCE(SUM("c_0359"), 0)
        INTO v_available
        FROM mrv."t_0021"
        WHERE "c_0401" = v_existing."c_0486"
          AND "c_0402" = 'v1'
          AND "c_0456" = v_existing."c_0458"
          AND "c_0457" = 'v1'
          AND "c_0102"::text = v_existing."c_0102"::text;

    ELSIF v_existing."c_0455"::text = '_' THEN
        SELECT COALESCE(SUM(pr."c_0359"), 0)
        INTO v_available
        FROM mrv."t_0021" pr
        JOIN mrv."t_0022" pf ON pf."c_0361" = pr.id
        WHERE pr."c_0401" = v_existing."c_0486"
          AND pr."c_0402" = 'v1'
          AND pf."c_0183" = v_existing."c_0458"
          AND pr."c_0102"::text = v_existing."c_0102"::text;

    ELSE
        RAISE EXCEPTION '_%_', v_existing."c_0455"::text;
    END IF;

    SELECT COALESCE(SUM("c_0381"), 0)
    INTO v_already_supplied
    FROM mrv."t_0028"
    WHERE "c_0486" = v_existing."c_0486"
      AND "c_0455"::text = v_existing."c_0455"::text
      AND "c_0458" = v_existing."c_0458"
      AND "c_0102"::text = v_existing."c_0102"::text
      AND id != p_0050;

    IF p_0080 > (v_available - v_already_supplied) THEN
        RAISE EXCEPTION '_%_%_%_%_%_',
            p_0080, (v_available - v_already_supplied),
            v_existing."c_0455"::text, v_existing."c_0458", v_existing."c_0102"::text;
    END IF;

    BEGIN
        UPDATE mrv."t_0028"
        SET
            "c_0170" = p_0026,
            "c_0381" = p_0080,
            "c_0489" = p_0107,
            "c_0528" = NOW()
        WHERE id = p_0050;

        IF NOT FOUND THEN
            RAISE EXCEPTION '_%_', p_0050;
        END IF;
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION '_';
    END;

    RETURN QUERY
        SELECT sv.id, sv."c_0486", sv."c_0170", sv."c_0455"::text, sv."c_0458",
               sv."c_0102"::text, sv."c_0381", sv."c_0489", sv."c_0094",
               sv."c_0093", sv."c_0528"
        FROM mrv."t_0028" sv WHERE sv.id = p_0050;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0090(
    p_0115 uuid
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_enterprise_id uuid;
    v_verifier_user_id uuid;
    v_updated_rows int;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT p_0001, c_0537
    INTO v_enterprise_id, v_verifier_user_id
    FROM public.t_0096
    WHERE id = p_0115;

    IF v_enterprise_id IS NULL THEN
        RAISE EXCEPTION '_%_', p_0115;
    END IF;

    IF NOT auth.f_0119(p_0026 => v_enterprise_id) THEN
        RAISE EXCEPTION '_';
    END IF;

    UPDATE public.t_0096
    SET c_0415 = now(), c_0416 = v_current_user_id
    WHERE id = p_0115
      AND c_0415 IS NULL;

    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
    IF v_updated_rows = 0 THEN
        RAISE EXCEPTION '_%_', p_0115;
    END IF;

    
    INSERT INTO audit.t_0097 (c_0537, p_0001, action, c_0141)
    VALUES (
        v_verifier_user_id,
        v_enterprise_id,
        '_',
        jsonb_build_object(
            '_', v_current_user_id,
            '_', p_0115
        )
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0091(
    p_0035 uuid
)
RETURNS TABLE (
    c_0425 uuid,
    c_0426 text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_entity_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT f."c_0172" INTO v_entity_id
    FROM mrv."t_0012" f
    WHERE f.id = p_0035;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_entity_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT (
        auth.f_0119(p_0026 => v_entity_id)
        OR auth.f_0119(p_0105 => v_entity_id)
        OR auth.f_0119(p_0037 => v_entity_id)
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN QUERY
    SELECT sp.id, sp.name
    FROM mrv."t_0037" vpf
    JOIN mrv."t_0033" vp ON vp.id = vpf."c_0369"
    JOIN mrv.t_0084 sp ON sp.c_0535 = vp.id
    WHERE vpf."c_0187" = p_0035
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0099(
    p_0105 uuid,
    p_0026 uuid,
    p_0097 text,
    p_0100 uuid,
    p_0016 text,
    p_0080 float8,
    p_0107 date
)
RETURNS TABLE(id uuid, "c_0486" uuid, "c_0170" uuid, "c_0455" text, "c_0458" uuid, "c_0102" text, "c_0381" double precision, "c_0489" date, "c_0094" uuid, "c_0093" timestamptz, "c_0528" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_farm RECORD;
    v_available float8 := 0;
    v_already_supplied float8;
    v_new_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0105 => p_0105) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    
    PERFORM pg_advisory_xact_lock(
        hashtext(p_0105::text || p_0097 || p_0100::text || p_0016)
    );

    BEGIN
        PERFORM p_0097::mrv."ty_0018";
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION '_%_', p_0097;
    END;

    BEGIN
        PERFORM p_0016::mrv."ty_0004";
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION '_%_', p_0016;
    END;

    IF p_0080 <= 0 OR p_0080 > 1000000 THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0021"
        WHERE "c_0401" = p_0105
          AND "c_0402" = 'v1'
          AND "c_0170" = p_0026
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0097 = '_' THEN
        SELECT id, "c_0172"
        INTO v_farm
        FROM mrv."t_0012"
        WHERE id = p_0100
        LIMIT 1;

        IF v_farm IS NULL OR v_farm."c_0172" != p_0105 THEN
            RAISE EXCEPTION '_%_%_',
                p_0100, p_0105;
        END IF;

        SELECT COALESCE(SUM(hr."c_0512"), 0)
        INTO v_available
        FROM mrv."t_0016" hr
        JOIN mrv."t_0006" c ON c.id = hr."c_0117"
        WHERE c."c_0102"::text = p_0016
          AND c.c_0472 = 'v1'
          AND c."c_0187" = v_farm.id;

    ELSIF p_0097 = '_' THEN
        SELECT COALESCE(SUM("c_0359"), 0)
        INTO v_available
        FROM mrv."t_0021"
        WHERE "c_0401" = p_0105
          AND "c_0402" = 'v1'
          AND "c_0456" = p_0100
          AND "c_0457" = 'v1'
          AND "c_0102"::text = p_0016;

    ELSIF p_0097 = '_' THEN
        SELECT COALESCE(SUM(pr."c_0359"), 0)
        INTO v_available
        FROM mrv."t_0021" pr
        JOIN mrv."t_0022" pf ON pf."c_0361" = pr.id
        WHERE pr."c_0401" = p_0105
          AND pr."c_0402" = 'v1'
          AND pf."c_0183" = p_0100
          AND pr."c_0102"::text = p_0016;

    ELSE
        RAISE EXCEPTION '_%_', p_0097;
    END IF;

    SELECT COALESCE(SUM("c_0381"), 0)
    INTO v_already_supplied
    FROM mrv."t_0028"
    WHERE "c_0486" = p_0105
      AND "c_0455"::text = p_0097
      AND "c_0458" = p_0100
      AND "c_0102"::text = p_0016;

    IF p_0080 > (v_available - v_already_supplied) THEN
        RAISE EXCEPTION '_%_%_%_%_%_',
            p_0080, (v_available - v_already_supplied),
            p_0097, p_0100, p_0016;
    END IF;

    v_new_id := gen_random_uuid();

    BEGIN
        INSERT INTO mrv."t_0028" (
            id,
            "c_0486",
            "c_0170",
            "c_0455",
            "c_0458",
            "c_0102",
            "c_0381",
            "c_0489",
            "c_0094",
            "c_0093",
            "c_0528"
        ) VALUES (
            v_new_id,
            p_0105,
            p_0026,
            p_0097::mrv."ty_0018",
            p_0100,
            p_0016::mrv."ty_0004",
            p_0080,
            p_0107,
            v_current_user_id,
            NOW(),
            NOW()
        );
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION '_';
    END;

    RETURN QUERY
        SELECT sv.id, sv."c_0486", sv."c_0170", sv."c_0455"::text, sv."c_0458",
               sv."c_0102"::text, sv."c_0381", sv."c_0489", sv."c_0094",
               sv."c_0093", sv."c_0528"
        FROM mrv."t_0028" sv WHERE sv.id = v_new_id;
END;
$$;



CREATE OR REPLACE FUNCTION mrv.f_0100(
    p_0105 uuid,
    p_0118 int,
    p_0026 uuid DEFAULT NULL
)
RETURNS TABLE (
    c_0518 double precision,
    c_0431 double precision,
    c_0434 double precision,
    c_0365 double precision,
    c_0105 text,
    c_0103 double precision
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT (
        auth.f_0119(p_0105 => p_0105)
        OR EXISTS (
            SELECT 1
            FROM public.t_0050 es
            WHERE es.p_0122 = p_0105
              AND auth.f_0119(p_0026 => es.p_0001)
        )
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0026 IS NOT NULL AND NOT auth.f_0119(p_0026 => p_0026) THEN
        RAISE EXCEPTION '_%_', p_0026;
    END IF;

    IF p_0118 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0118 < 2000 OR p_0118 > EXTRACT(YEAR FROM NOW())::int + 5 THEN
        RAISE EXCEPTION '_%_', p_0118;
    END IF;

    RETURN QUERY
    WITH scope1_farms AS (
        SELECT f.id AS p_0004
        FROM mrv."t_0012" f
        WHERE f."c_0172" = p_0105
            AND f."ty_0016" = 'v1'
    ),
    scope3_farms AS (
        SELECT f.id AS p_0004
        FROM mrv."t_0012" f
        WHERE f."c_0172" = p_0105
            AND f."ty_0016" = 'v1'
    ),
    all_supplier_farm_ids AS (
        SELECT p_0004 FROM scope1_farms
        UNION ALL
        SELECT p_0004 FROM scope3_farms
    ),
    
    supplier_farm_carbon AS (
        SELECT bcd.p_0004, bcd.c_0060
        FROM mrv.f_0016(
            ARRAY(SELECT p_0004 FROM all_supplier_farm_ids),
            p_0118
        ) bcd
    ),
    
    supplier_farm_cultivations AS (
        SELECT c."c_0187" AS p_0004, c."c_0102"::text AS c_0105
        FROM mrv."t_0006" c
        WHERE c."c_0187" IN (SELECT p_0004 FROM all_supplier_farm_ids)
            AND c.c_0472 = 'v1'
            AND c."c_0222" >= make_date(p_0118, 1, 1)
            AND c."c_0222" <= make_date(p_0118, 12, 31)
    ),
    
    scope1_by_crop AS (
        SELECT
            sfc.c_0105,
            SUM(
                COALESCE(sfc2.c_0060, 0) / NULLIF(cnt.cultivation_count, 0)
            ) AS c_0059
        FROM supplier_farm_cultivations sfc
        JOIN scope1_farms sf ON sf.p_0004 = sfc.p_0004
        JOIN supplier_farm_carbon sfc2 ON sfc2.p_0004 = sfc.p_0004
        JOIN (
            SELECT p_0004, COUNT(*) AS cultivation_count
            FROM supplier_farm_cultivations
            GROUP BY p_0004
        ) cnt ON cnt.p_0004 = sfc.p_0004
        GROUP BY sfc.c_0105
    ),
    
    scope3_by_crop AS (
        SELECT
            sfc.c_0105,
            SUM(
                COALESCE(sfc2.c_0060, 0) / NULLIF(cnt.cultivation_count, 0)
            ) AS c_0059
        FROM supplier_farm_cultivations sfc
        JOIN scope3_farms sf ON sf.p_0004 = sfc.p_0004
        JOIN supplier_farm_carbon sfc2 ON sfc2.p_0004 = sfc.p_0004
        JOIN (
            SELECT p_0004, COUNT(*) AS cultivation_count
            FROM supplier_farm_cultivations
            GROUP BY p_0004
        ) cnt ON cnt.p_0004 = sfc.p_0004
        GROUP BY sfc.c_0105
    ),
    
    scope1_total AS (
        SELECT COALESCE(SUM(c_0060), 0) AS total
        FROM supplier_farm_carbon sfc
        WHERE sfc.p_0004 IN (SELECT p_0004 FROM scope1_farms)
    ),
    scope3_total AS (
        SELECT COALESCE(SUM(c_0060), 0) AS total
        FROM supplier_farm_carbon sfc
        WHERE sfc.p_0004 IN (SELECT p_0004 FROM scope3_farms)
    ),
    
    procurements AS (
        SELECT
            p.id,
            p."c_0102"::text AS c_0105,
            p."c_0456",
            p."c_0359"
        FROM mrv."t_0021" p
        WHERE p."c_0401" = p_0105
            AND p."c_0402" = 'v1'
            AND p."c_0457" = 'v1'
            AND p."c_0360" >= make_date(p_0118, 1, 1)
            AND p."c_0360" <= make_date(p_0118, 12, 31)
            AND p."c_0359" IS NOT NULL
            AND p."c_0359" > 0
            AND (p_0026 IS NULL OR p."c_0170" = p_0026)
    ),
    
    farmer_farms AS (
        SELECT f.id AS p_0004, f."c_0172" AS con_0122
        FROM mrv."t_0012" f
        WHERE f."c_0172" IN (SELECT DISTINCT "c_0456" FROM procurements)
    ),
    farmer_farm_carbon AS (
        SELECT bcd.p_0004, bcd.c_0060
        FROM mrv.f_0016(
            ARRAY(SELECT p_0004 FROM farmer_farms),
            p_0118
        ) bcd
    ),
    
    farmer_yields AS (
        SELECT
            f."c_0172",
            c."c_0102"::text AS c_0105,
            SUM(COALESCE(hr."c_0512", 0)) AS c_0521
        FROM mrv."t_0016" hr
        JOIN mrv."t_0006" c ON c.id = hr."c_0117"
        JOIN mrv."t_0012" f ON f.id = c."c_0187"
        WHERE f."c_0172" IN (SELECT DISTINCT "c_0456" FROM procurements)
            AND c.c_0472 = 'v1'
            AND c."c_0222" >= make_date(p_0118, 1, 1)
            AND c."c_0222" <= make_date(p_0118, 12, 31)
        GROUP BY f."c_0172", c."c_0102"::text
    ),
    
    procurement_carbon AS (
        SELECT
            proc.c_0105,
            SUM(
                CASE WHEN fy.c_0521 > 0 THEN
                    LEAST(proc."c_0359" / fy.c_0521, 1.0) *
                    COALESCE((
                        SELECT SUM(ffc.c_0060)
                        FROM farmer_farm_carbon ffc
                        WHERE ffc.p_0004 IN (
                            SELECT p_0004 FROM farmer_farms WHERE con_0122 = proc."c_0456"
                        )
                    ), 0)
                ELSE 0
                END
            ) AS c_0059
        FROM procurements proc
        LEFT JOIN farmer_yields fy
            ON fy."c_0172" = proc."c_0456"
            AND fy.c_0105 = proc.c_0105
        GROUP BY proc.c_0105
    ),
    
    all_by_crop AS (
        SELECT c_0105, c_0059 FROM scope1_by_crop
        UNION ALL
        SELECT c_0105, c_0059 FROM scope3_by_crop
        UNION ALL
        SELECT c_0105, c_0059 FROM procurement_carbon
    ),
    merged_by_crop AS (
        SELECT c_0105, SUM(c_0059) AS c_0059
        FROM all_by_crop
        GROUP BY c_0105
    )
    SELECT
        (SELECT total FROM scope1_total) + (SELECT total FROM scope3_total) +
            COALESCE((SELECT SUM(c_0059) FROM procurement_carbon), 0) AS c_0518,
        (SELECT total FROM scope1_total) AS c_0431,
        (SELECT total FROM scope3_total) AS c_0434,
        COALESCE((SELECT SUM(c_0059) FROM procurement_carbon), 0) AS c_0365,
        mbc.c_0105,
        mbc.c_0059 AS c_0103
    FROM merged_by_crop mbc
    UNION ALL
    
    SELECT
        (SELECT total FROM scope1_total) + (SELECT total FROM scope3_total) +
            COALESCE((SELECT SUM(c_0059) FROM procurement_carbon), 0),
        (SELECT total FROM scope1_total),
        (SELECT total FROM scope3_total),
        COALESCE((SELECT SUM(c_0059) FROM procurement_carbon), 0),
        NULL,
        NULL
    WHERE NOT EXISTS (SELECT 1 FROM merged_by_crop);
END;
$$;




CREATE OR REPLACE FUNCTION mrv.f_0101()
RETURNS TRIGGER AS $$
DECLARE
  existing_farm_id UUID;
  existing_polygon_id UUID;
BEGIN
  
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  
  IF TG_TABLE_NAME = 'v1' THEN
    IF NEW."c_0355" IS NOT NULL AND (TG_OP = '_' OR NEW."c_0355" IS DISTINCT FROM OLD."c_0355") THEN
      SELECT "c_0187" INTO existing_farm_id
      FROM mrv."Polygon"
      WHERE id = NEW."c_0355";

      IF existing_farm_id IS NOT NULL AND existing_farm_id <> NEW.id THEN
        RAISE EXCEPTION '_%_%_', NEW."c_0355", existing_farm_id;
      END IF;

      IF TG_OP = '_' AND OLD."c_0355" IS NOT NULL AND OLD."c_0355" <> NEW."c_0355" THEN
        UPDATE mrv."Polygon" SET "c_0187" = NULL, "c_0528" = NOW() WHERE id = OLD."c_0355";
      END IF;

      UPDATE mrv."Polygon"
      SET "c_0187" = NEW.id, "c_0528" = NOW()
      WHERE id = NEW."c_0355";
    END IF;

  ELSIF TG_TABLE_NAME = 'v1' THEN
    IF NEW."c_0187" IS NOT NULL AND (TG_OP = '_' OR NEW."c_0187" IS DISTINCT FROM OLD."c_0187") THEN
      SELECT "c_0355" INTO existing_polygon_id
      FROM mrv."t_0012"
      WHERE id = NEW."c_0187";

      IF existing_polygon_id IS NOT NULL AND existing_polygon_id <> NEW.id THEN
        RAISE EXCEPTION '_%_%_', NEW."c_0187", existing_polygon_id;
      END IF;

      IF TG_OP = '_' AND OLD."c_0187" IS NOT NULL AND OLD."c_0187" <> NEW."c_0187" THEN
        RAISE EXCEPTION '_%_%_', NEW.id, OLD."c_0187";
      END IF;

      UPDATE mrv."t_0012"
      SET "c_0355" = NEW.id, "c_0528" = NOW()
      WHERE id = NEW."c_0187";
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION mrv.f_0103(
    p_0073 uuid,
    p_0087 jsonb
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_supplier_id uuid;
    v_updated_rows int;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (auth.f_0066() -> '_' -> '_' ->> 0)::uuid;
    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    UPDATE mrv."t_0001"
    SET
        c_0413 = p_0087,
        "c_0528" = NOW()
    WHERE mrv."t_0001".id = p_0073
      AND mrv."t_0001"."c_0172" = v_supplier_id;

    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
    IF v_updated_rows = 0 THEN
        RAISE EXCEPTION '_%_', p_0073;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0104(
    p_0073 uuid,
    p_0102 text,
    p_0064 uuid,
    p_0030 text
)
RETURNS TABLE (
    id uuid,
    con_0122 uuid,
    c_0294 text,
    c_0329 timestamptz,
    c_0273 uuid,
    c_0472 text,
    c_0219 text,
    c_0497 int,
    c_0498 double precision,
    c_0127 double precision,
    c_0037 boolean[],
    c_0264 boolean,
    c_0124 boolean[],
    c_0266 boolean,
    c_0126 double precision,
    c_0265 boolean,
    c_0125 double precision,
    c_0128 text,
    c_0267 boolean,
    c_0210 boolean[],
    c_0269 boolean,
    c_0212 double precision,
    c_0268 boolean,
    c_0211 double precision,
    c_0213 text,
    c_0176 text,
    c_0413 jsonb,
    c_0190 uuid[],
    c_0095 timestamptz,
    c_0529 timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_supplier_id uuid;
    v_updated_rows int;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_supplier_id := (auth.f_0066() -> '_' -> '_' ->> 0)::uuid;
    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    UPDATE mrv."t_0001"
    SET
        c_0472 = p_0102::mrv."ty_0002",
        "c_0272" = COALESCE(p_0064, "c_0272"),
        "c_0175" = p_0030,
        "c_0528" = NOW()
    WHERE mrv."t_0001".id = p_0073
      AND mrv."t_0001"."c_0172" = v_supplier_id;

    GET DIAGNOSTICS v_updated_rows = ROW_COUNT;
    IF v_updated_rows = 0 THEN
        RAISE EXCEPTION '_%_', p_0073;
    END IF;

    RETURN QUERY
    SELECT
        cp.id,
        cp."c_0172",
        cp.c_0294,
        cp."c_0328",
        cp."c_0272",
        cp.c_0472::text,
        cp."c_0218"::text,
        cp."c_0494",
        cp."c_0495",
        cp."c_0121",
        cp."c_0036",
        cp."c_0251",
        cp."c_0118",
        cp."c_0253",
        cp."c_0120",
        cp."c_0252",
        cp."c_0119",
        cp."c_0122"::text,
        cp."c_0254",
        cp."c_0206",
        cp."c_0256",
        cp."c_0208",
        cp."c_0255",
        cp."c_0207",
        cp."c_0209"::text,
        cp."c_0175",
        cp.c_0413,
        ARRAY(SELECT cpf."c_0187" FROM mrv."t_0002" cpf WHERE cpf."c_0058" = cp.id AND cpf."c_0187" IS NOT NULL),
        cp."c_0093",
        cp."c_0528"
    FROM mrv."t_0001" cp
    WHERE cp.id = p_0073;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0106(p_0023 jsonb)
RETURNS TABLE (
    id uuid,
    "c_0187" uuid,
    "c_0057" int,
    "c_0226" boolean,
    "c_0225" boolean,
    "c_0292" float8,
    "c_0483" timestamptz,
    "c_0093" timestamptz,
    "c_0528" timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_entity_id uuid;
    v_farm_id uuid;
    v_calendar_year int;
    v_has_trees boolean;
    v_has_tree_mortality boolean;
    v_live_tree_area_ha float8;
    v_tree_species_inventories jsonb;
    v_survey_id uuid;
    v_item jsonb;
    v_result RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_entity_id := (p_0023->>'_')::uuid;

    IF v_entity_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_farm_id := (p_0023->>'_')::uuid;
    v_calendar_year := (p_0023->>'_')::int;
    v_has_trees := (p_0023->>'_')::boolean;
    v_has_tree_mortality := (p_0023->>'_')::boolean;
    v_live_tree_area_ha := (p_0023->>'_')::float8;
    v_tree_species_inventories := p_0023->'_';

    
    
    IF NOT (
        auth.f_0119(p_0026 => v_entity_id)
        OR auth.f_0119(p_0105 => v_entity_id)
        OR auth.f_0119(p_0037 => v_entity_id)
    ) THEN
        RAISE EXCEPTION '_%_', v_entity_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0012"
        WHERE id = v_farm_id AND "c_0172" = v_entity_id
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT id INTO v_survey_id
    FROM mrv."t_0008"
    WHERE "c_0187" = v_farm_id AND "c_0057" = v_calendar_year;

    IF v_survey_id IS NOT NULL THEN
        UPDATE mrv."t_0008"
        SET "c_0226" = v_has_trees,
            "c_0225" = v_has_tree_mortality,
            "c_0292" = v_live_tree_area_ha,
            "c_0483" = NOW(),
            "c_0528" = NOW()
        WHERE mrv."t_0008".id = v_survey_id
        RETURNING * INTO v_result;
    ELSE
        INSERT INTO mrv."t_0008" (
            id, "c_0187", "c_0057",
            "c_0226", "c_0225", "c_0292",
            "c_0483", "c_0093", "c_0528"
        ) VALUES (
            gen_random_uuid(),
            v_farm_id,
            v_calendar_year,
            v_has_trees,
            v_has_tree_mortality,
            v_live_tree_area_ha,
            NOW(), NOW(), NOW()
        )
        RETURNING * INTO v_result;

        v_survey_id := v_result.id;
    END IF;

    IF v_tree_species_inventories IS NOT NULL
        AND jsonb_typeof(v_tree_species_inventories) = '_'
        AND jsonb_array_length(v_tree_species_inventories) > 0
    THEN
        DELETE FROM mrv."t_0030"
        WHERE "c_0490" = v_survey_id;

        FOR v_item IN SELECT * FROM jsonb_array_elements(v_tree_species_inventories)
        LOOP
            INSERT INTO mrv."t_0030" (
                id, "c_0187", "c_0057", "c_0490",
                "c_0468", "c_0030", "c_0031",
                "c_0293", "c_0133",
                "c_0522", "c_0134",
                "c_0093", "c_0528"
            ) VALUES (
                gen_random_uuid(),
                v_farm_id,
                v_calendar_year,
                v_survey_id,
                (v_item->>'_')::mrv."ty_0020",
                (v_item->>'_')::float8,
                (v_item->>'_')::float8,
                (v_item->>'_')::int,
                (v_item->>'_')::int,
                (v_item->>'_')::float8,
                (v_item->>'_')::float8,
                NOW(), NOW()
            );
        END LOOP;
    END IF;

    
    IF v_has_trees AND v_tree_species_inventories IS NOT NULL AND jsonb_array_length(v_tree_species_inventories) = 0 THEN
        DELETE FROM mrv."t_0030"
        WHERE "c_0187" = v_farm_id
        AND "c_0057" = v_calendar_year;
    END IF;

    
    IF NOT v_has_trees THEN
        DELETE FROM mrv."t_0030"
        WHERE "c_0187" = v_farm_id
        AND "c_0057" = v_calendar_year;
    END IF;

    RETURN QUERY SELECT
        v_result.id,
        v_result."c_0187"::uuid,
        v_result."c_0057"::int,
        v_result."c_0226"::boolean,
        v_result."c_0225"::boolean,
        v_result."c_0292"::float8,
        v_result."c_0483"::timestamptz,
        v_result."c_0093"::timestamptz,
        v_result."c_0528"::timestamptz;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0107(
    p_0039 jsonb
)
RETURNS TABLE (
    id uuid,
    name text,
    c_0356 uuid,
    c_0279 text,
    c_0104 uuid,
    c_0107 text[]
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_item jsonb;
    v_farm_id uuid;
    v_polygon_id uuid;
    v_entity_id uuid;
    v_name text;
    v_country_code text;
    v_scope text;
    v_land_ownership text;
    v_geometry jsonb;
    v_new_geometry geometry;
    v_existing_polygon RECORD;
    v_overlapping_farm RECORD;
    v_farm RECORD;
    v_crop_plan_id uuid;
    v_crop_histories jsonb;
    v_crop_item jsonb;
    v_crop_records jsonb;
    v_crop_type text;
    v_crop_types text[];
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0039 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF jsonb_typeof(p_0039) != '_' THEN
        RAISE EXCEPTION '_%_', jsonb_typeof(p_0039);
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_0039)
    LOOP
        v_name := v_item->>'_';
        v_country_code := v_item->>'_';
        v_scope := v_item->>'_';
        v_land_ownership := v_item->>'_';
        v_geometry := v_item->'_'->'_';
        v_crop_histories := v_item->'_';

        v_entity_id := (v_item->>'_')::uuid;
        IF NOT (
            auth.f_0119(p_0026 => v_entity_id)
            OR auth.f_0119(p_0105 => v_entity_id)
            OR auth.f_0119(p_0037 => v_entity_id)
        ) THEN
            RAISE EXCEPTION '_%_', v_entity_id;
        END IF;

        IF v_name IS NULL OR v_name = 'v1' THEN
            RAISE EXCEPTION '_';
        END IF;

        
        BEGIN
            v_farm_id := (v_item->>'_')::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            v_farm_id := NULL;
        END;

        IF v_farm_id IS NULL THEN
            
            SELECT f.id INTO v_farm_id
            FROM mrv."t_0012" f
            WHERE f."c_0172" = v_entity_id AND f."name" = v_name;
        END IF;

        IF v_farm_id IS NULL THEN
            v_farm_id := gen_random_uuid();
        END IF;

        
        BEGIN
            v_polygon_id := COALESCE(
                (v_item->>'_')::uuid,
                (v_item->'_'->>'_')::uuid
            );
        EXCEPTION WHEN invalid_text_representation THEN
            v_polygon_id := NULL;
        END;

        IF v_polygon_id IS NULL THEN
            v_polygon_id := gen_random_uuid();
        END IF;

        
        IF v_geometry IS NOT NULL AND v_geometry::text != '_' THEN
            v_new_geometry := ST_SetSRID(ST_GeomFromGeoJSON(v_geometry::text), 4326);

            SELECT f.id, f."name" INTO v_overlapping_farm
            FROM mrv."t_0012" f
            JOIN mrv."Polygon" p ON p.id = f."c_0355"
            WHERE f."c_0172" = v_entity_id
              AND f.id != v_farm_id
              AND ST_Intersects(p.geometry::geography, v_new_geometry::geography)
              AND NOT ST_Touches(p.geometry, v_new_geometry)
            LIMIT 1;

            IF FOUND THEN
                RAISE EXCEPTION '_%_%_', v_overlapping_farm."name", v_overlapping_farm.id;
            END IF;

            INSERT INTO mrv."Polygon" (id, geometry, "c_0093", "c_0528")
            VALUES (
                v_polygon_id,
                v_new_geometry,
                NOW(),
                NOW()
            )
            ON CONFLICT (id) DO UPDATE SET
                geometry = v_new_geometry,
                "c_0528" = NOW();
        ELSE
            SELECT p.id, p."c_0187"
            INTO v_existing_polygon
            FROM mrv."Polygon" p
            WHERE p.id = v_polygon_id;

            IF v_existing_polygon IS NULL THEN
                RAISE EXCEPTION '_%_', v_polygon_id;
            END IF;

            IF v_existing_polygon."c_0187" IS NOT NULL AND v_existing_polygon."c_0187" != v_farm_id THEN
                RAISE EXCEPTION '_%_', v_polygon_id;
            END IF;
        END IF;

        
        IF v_country_code IS NOT NULL THEN
            BEGIN
                PERFORM v_country_code::mrv."ty_0003";
            EXCEPTION WHEN invalid_text_representation THEN
                RAISE EXCEPTION '_%_', v_country_code;
            END;
        END IF;

        IF v_scope IS NOT NULL THEN
            BEGIN
                PERFORM v_scope::mrv."ty_0016";
            EXCEPTION WHEN invalid_text_representation THEN
                RAISE EXCEPTION '_%_', v_scope;
            END;
        END IF;

        IF v_land_ownership IS NOT NULL THEN
            BEGIN
                PERFORM v_land_ownership::mrv."ty_0013";
            EXCEPTION WHEN invalid_text_representation THEN
                RAISE EXCEPTION '_%_', v_land_ownership;
            END;
        END IF;

        
        INSERT INTO mrv."t_0012" (
            id, "name", "c_0355", "c_0172",
            "ty_0003", "ty_0016", "ty_0013",
            "c_0093", "c_0528"
        ) VALUES (
            v_farm_id,
            v_name,
            v_polygon_id,
            v_entity_id,
            v_country_code::mrv."ty_0003",
            v_scope::mrv."ty_0016",
            v_land_ownership::mrv."ty_0013",
            NOW(),
            NOW()
        )
        ON CONFLICT (id) DO UPDATE SET
            "name" = EXCLUDED."name",
            "c_0355" = EXCLUDED."c_0355",
            "ty_0003" = COALESCE(EXCLUDED."ty_0003", mrv."t_0012"."ty_0003"),
            "ty_0016" = COALESCE(EXCLUDED."ty_0016", mrv."t_0012"."ty_0016"),
            "ty_0013" = COALESCE(EXCLUDED."ty_0013", mrv."t_0012"."ty_0013"),
            "c_0528" = NOW()
        RETURNING * INTO v_farm;

        
        v_crop_plan_id := NULL;
        v_crop_types := ARRAY[]::text[];

        IF v_crop_histories IS NOT NULL AND jsonb_array_length(v_crop_histories) > 0 THEN
            v_crop_item := v_crop_histories->0;
            v_crop_records := v_crop_item->'_';

            
            SELECT cp.id INTO v_crop_plan_id
            FROM mrv."t_0005" cp
            WHERE cp."c_0187" = v_farm.id
            LIMIT 1;

            IF v_crop_plan_id IS NULL THEN
                v_crop_plan_id := gen_random_uuid();
                INSERT INTO mrv."t_0005" (id, "c_0187", "c_0470")
                VALUES (v_crop_plan_id, v_farm.id, NOW());
            END IF;

            
            DELETE FROM mrv."t_0004" WHERE "c_0101" = v_crop_plan_id;

            
            IF v_crop_records IS NOT NULL AND jsonb_array_length(v_crop_records) > 0 THEN
                FOR v_crop_item IN SELECT * FROM jsonb_array_elements(v_crop_records)
                LOOP
                    v_crop_type := v_crop_item->>'_';

                    IF v_crop_type IS NOT NULL THEN
                        BEGIN
                            PERFORM v_crop_type::mrv."ty_0004";
                        EXCEPTION WHEN invalid_text_representation THEN
                            RAISE EXCEPTION '_%_', v_crop_type;
                        END;

                        INSERT INTO mrv."t_0004" (id, "c_0102", "c_0101", "c_0351")
                        VALUES (gen_random_uuid(), v_crop_type::mrv."ty_0004", v_crop_plan_id, NOW());

                        v_crop_types := array_append(v_crop_types, v_crop_type);
                    END IF;
                END LOOP;
            END IF;
        END IF;

        RETURN QUERY SELECT
            v_farm.id,
            v_farm."name",
            v_farm."c_0355",
            v_farm."ty_0013"::text,
            v_crop_plan_id,
            v_crop_types;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0108(
    p_0027 uuid,
    p_0017 uuid,
    p_0041 jsonb
)
RETURNS TABLE (
    id uuid,
    "c_0198" text,
    c_0010 float8,
    "c_0017" timestamptz,
    "c_0079" uuid,
    "c_0117" uuid,
    "c_0093" timestamptz,
    "c_0528" timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_current_user_id uuid;
    v_cultivation RECORD;
    v_item jsonb;
    v_fertilizer_id uuid;
    v_fertilizer_type text;
    v_amount float8;
    v_application_date timestamptz;
    v_compound_unit_id uuid;
    v_result RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT (
        auth.f_0119(p_0026 => p_0027)
        OR auth.f_0119(p_0105 => p_0027)
        OR auth.f_0119(p_0037 => p_0027)
    ) THEN
        RAISE EXCEPTION '_%_', p_0027;
    END IF;

    IF p_0041 IS NULL OR jsonb_typeof(p_0041) != '_' THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT c.id, c."c_0187"
    INTO v_cultivation
    FROM mrv."t_0006" c
    JOIN mrv."t_0012" f ON f.id = c."c_0187"
    WHERE c.id = p_0017 AND f."c_0172" = p_0027;

    IF v_cultivation IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_0041) AS fert
        WHERE NOT EXISTS (
            SELECT 1 FROM mrv."t_0003" cu
            WHERE cu.id = (fert->>'_')::uuid
        )
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_0041)
    LOOP
        v_fertilizer_id := (v_item->>'_')::uuid;
        v_fertilizer_type := v_item->>'_';
        v_amount := (v_item->>'_')::float8;
        v_application_date := (v_item->>'_')::timestamptz;
        v_compound_unit_id := (v_item->>'_')::uuid;

        BEGIN
            PERFORM v_fertilizer_type::mrv."ty_0010";
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION '_%_', v_fertilizer_type;
        END;

        IF v_fertilizer_id IS NOT NULL THEN
            IF NOT EXISTS (
                SELECT 1 FROM mrv."t_0014" fa
                JOIN mrv."t_0006" c ON c.id = fa."c_0117"
                JOIN mrv."t_0012" f ON f.id = c."c_0187"
                WHERE fa.id = v_fertilizer_id AND f."c_0172" = p_0027
            ) THEN
                RAISE EXCEPTION '_%_', v_fertilizer_id;
            END IF;

            UPDATE mrv."t_0014"
            SET "c_0198" = v_fertilizer_type::mrv."ty_0010",
                c_0010 = v_amount,
                "c_0017" = v_application_date,
                "c_0079" = v_compound_unit_id,
                "c_0117" = p_0017,
                "c_0528" = NOW()
            WHERE mrv."t_0014".id = v_fertilizer_id
            RETURNING * INTO v_result;
        ELSE
            INSERT INTO mrv."t_0014" (
                id, "c_0198", c_0010, "c_0017", "c_0079", "c_0117",
                "c_0093", "c_0528"
            ) VALUES (
                gen_random_uuid(), v_fertilizer_type::mrv."ty_0010", v_amount, v_application_date,
                v_compound_unit_id, p_0017, NOW(), NOW()
            )
            RETURNING * INTO v_result;
        END IF;

        RETURN QUERY SELECT
            v_result.id,
            v_result."c_0198"::text,
            v_result.c_0010::float8,
            v_result."c_0017"::timestamptz,
            v_result."c_0079"::uuid,
            v_result."c_0117"::uuid,
            v_result."c_0093"::timestamptz,
            v_result."c_0528"::timestamptz;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0109(p_0023 jsonb)
RETURNS TABLE (
    id uuid,
    "c_0512" float8,
    "c_0222" timestamptz,
    "c_0405" int,
    "c_0406" int,
    "c_0408" int,
    "c_0407" int,
    "c_0117" uuid,
    "c_0452" uuid,
    "c_0093" timestamptz,
    "c_0528" timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_entity_id uuid;
    v_cultivation_id uuid;
    v_total_yield float8;
    v_harvest_date timestamptz;
    v_residue_burned int;
    v_residue_incorporated int;
    v_residue_removed int;
    v_residue_other int;
    v_soil_report_id uuid;
    v_farm_id uuid;
    v_result RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_entity_id := (p_0023->>'_')::uuid;

    
    
    IF NOT (
        auth.f_0119(p_0026 => v_entity_id)
        OR auth.f_0119(p_0105 => v_entity_id)
        OR auth.f_0119(p_0037 => v_entity_id)
    ) THEN
        RAISE EXCEPTION '_%_', v_entity_id;
    END IF;

    v_cultivation_id := (p_0023->>'_')::uuid;
    v_total_yield := (p_0023->>'_')::float8;
    v_harvest_date := (p_0023->>'_')::timestamptz;
    v_residue_burned := (p_0023->>'_')::int;
    v_residue_incorporated := (p_0023->>'_')::int;
    v_residue_removed := (p_0023->>'_')::int;
    v_residue_other := (p_0023->>'_')::int;
    v_soil_report_id := (p_0023->>'_')::uuid;

    SELECT c."c_0187" INTO v_farm_id
    FROM mrv."t_0006" c
    JOIN mrv."t_0012" f ON f.id = c."c_0187"
    WHERE c.id = v_cultivation_id AND f."c_0172" = v_entity_id;

    IF v_farm_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_soil_report_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM mrv."t_0027"
            WHERE id = v_soil_report_id
            AND "c_0187" = v_farm_id
        ) THEN
            RAISE EXCEPTION '_';
        END IF;
    END IF;

    IF v_residue_burned + v_residue_incorporated + v_residue_removed + v_residue_other != 100 THEN
        RAISE EXCEPTION '_';
    END IF;

    UPDATE mrv."t_0006"
    SET c_0472 = 'v1',
        "c_0222" = v_harvest_date,
        "c_0528" = NOW()
    WHERE mrv."t_0006".id = v_cultivation_id;

    INSERT INTO mrv."t_0016" (
        id, "c_0512", "c_0222", "c_0405", "c_0406",
        "c_0408", "c_0407", "c_0117", "c_0452",
        "c_0093", "c_0528"
    ) VALUES (
        gen_random_uuid(), v_total_yield, v_harvest_date, v_residue_burned, v_residue_incorporated,
        v_residue_removed, v_residue_other, v_cultivation_id, v_soil_report_id,
        NOW(), NOW()
    )
    ON CONFLICT ("c_0117")
    DO UPDATE SET
        "c_0512" = EXCLUDED."c_0512",
        "c_0222" = EXCLUDED."c_0222",
        "c_0405" = EXCLUDED."c_0405",
        "c_0406" = EXCLUDED."c_0406",
        "c_0408" = EXCLUDED."c_0408",
        "c_0407" = EXCLUDED."c_0407",
        "c_0452" = COALESCE(EXCLUDED."c_0452", mrv."t_0016"."c_0452"),
        "c_0528" = NOW()
    RETURNING * INTO v_result;

    RETURN QUERY SELECT
        v_result.id,
        v_result."c_0512"::float8,
        v_result."c_0222"::timestamptz,
        v_result."c_0405"::int,
        v_result."c_0406"::int,
        v_result."c_0408"::int,
        v_result."c_0407"::int,
        v_result."c_0117"::uuid,
        v_result."c_0452"::uuid,
        v_result."c_0093"::timestamptz,
        v_result."c_0528"::timestamptz;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0110(p_0023 jsonb)
RETURNS TABLE (
    id uuid,
    "c_0187" uuid,
    "c_0422" timestamptz,
    "c_0093" timestamptz,
    "c_0528" timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_entity_id uuid;
    v_farm_id uuid;
    v_soil_report_id uuid;
    v_sample_collection_date timestamptz;
    v_measurements jsonb;
    v_item jsonb;
    v_parameter text;
    v_value float8;
    v_compound_unit_id uuid;
    v_result RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    v_entity_id := (p_0023->>'_')::uuid;

    
    
    IF NOT (
        auth.f_0119(p_0026 => v_entity_id)
        OR auth.f_0119(p_0105 => v_entity_id)
        OR auth.f_0119(p_0037 => v_entity_id)
    ) THEN
        RAISE EXCEPTION '_%_', v_entity_id;
    END IF;

    v_farm_id := (p_0023->>'_')::uuid;
    v_soil_report_id := (p_0023->>'_')::uuid;
    v_sample_collection_date := (p_0023->>'_')::timestamptz;
    v_measurements := p_0023->'_';

    IF v_measurements IS NULL OR jsonb_typeof(v_measurements) != '_' OR jsonb_array_length(v_measurements) = 0 THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0012"
        WHERE id = v_farm_id AND "c_0172" = v_entity_id
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_measurements) AS m
        WHERE NOT EXISTS (
            SELECT 1 FROM mrv."t_0003" cu
            WHERE cu.id = (m->>'_')::uuid
        )
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_soil_report_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM mrv."t_0027"
            WHERE id = v_soil_report_id AND "c_0187" = v_farm_id
        ) THEN
            RAISE EXCEPTION '_';
        END IF;

        UPDATE mrv."t_0027"
        SET "c_0422" = v_sample_collection_date,
            "c_0528" = NOW()
        WHERE mrv."t_0027".id = v_soil_report_id
        RETURNING * INTO v_result;

        DELETE FROM mrv."t_0026"
        WHERE "c_0452" = v_soil_report_id;
    ELSE
        INSERT INTO mrv."t_0027" (
            id, "c_0187", "c_0422", "c_0093", "c_0528"
        ) VALUES (
            gen_random_uuid(), v_farm_id, v_sample_collection_date, NOW(), NOW()
        )
        RETURNING * INTO v_result;

        v_soil_report_id := v_result.id;
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_measurements)
    LOOP
        v_parameter := v_item->>'_';
        v_value := (v_item->>'_')::float8;
        v_compound_unit_id := (v_item->>'_')::uuid;

        BEGIN
            PERFORM v_parameter::mrv."ty_0009";
        EXCEPTION WHEN invalid_text_representation THEN
            RAISE EXCEPTION '_%_', v_parameter;
        END;

        INSERT INTO mrv."t_0026" (
            id, "c_0187", "c_0452", c_0339, value, "c_0079",
            "c_0093", "c_0528"
        ) VALUES (
            gen_random_uuid(), v_farm_id, v_soil_report_id,
            v_parameter::mrv."ty_0009", v_value, v_compound_unit_id,
            NOW(), NOW()
        );
    END LOOP;

    RETURN QUERY SELECT
        v_result.id,
        v_result."c_0187"::uuid,
        v_result."c_0422"::timestamptz,
        v_result."c_0093"::timestamptz,
        v_result."c_0528"::timestamptz;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0114(
    p_0029 text,
    p_0027 uuid
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_metadata_str text;
    v_rbac_context jsonb;
    v_entities jsonb;
BEGIN
    v_metadata_str := nullif(current_setting('_', true), '_');
    IF v_metadata_str IS NULL THEN
        RETURN false;
    END IF;

    BEGIN
        v_rbac_context := v_metadata_str::jsonb -> '_';
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN false;
    END;

    IF v_rbac_context IS NULL THEN
        RETURN false;
    END IF;

    IF p_0029 = '_' THEN
        v_entities := v_rbac_context -> '_';
    ELSIF p_0029 = '_' THEN
        v_entities := v_rbac_context -> '_';
    ELSIF p_0029 = '_' THEN
        v_entities := v_rbac_context -> '_';
    ELSE
        RETURN false;
    END IF;

    RETURN v_entities IS NOT NULL
        AND v_entities @> to_jsonb(lower(p_0027::text));
END;
$$;





CREATE OR REPLACE FUNCTION mrv.f_0127(
    p_0025 text,
    p_0089 text,           
    p_0054 text, 
    p_0072 uuid DEFAULT NULL,
    p_0028 text DEFAULT NULL
)
RETURNS TABLE(
    f_0041 text,
    role text,
    c_0240 text,
    c_0132 text,
    c_0242 uuid,
    p_0001 uuid,
    c_0171 text,
    p_0122 uuid,
    c_0488 text,
    p_0005 uuid,
    c_0194 text,
    c_0336 text,
    c_0532 text,
    c_0243 text
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_metadata_str text;
    v_rbac_context jsonb;
    v_permissions jsonb;
    v_level text;
    v_user_enterprise_id uuid;
    v_user_supplier_id uuid;
    v_inviter_email text;
    v_db_role text;
    v_enterprise_id uuid;
    v_enterprise_name text;
    v_supplier_id uuid;
    v_supplier_name text;
    v_farmer_id uuid;
    v_farmer_name text;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    v_metadata_str := nullif(current_setting('_', true), '_');
    IF v_metadata_str IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    BEGIN
        v_rbac_context := v_metadata_str::jsonb -> '_';
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION '_';
    END;

    IF v_rbac_context IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    
    v_permissions := v_rbac_context -> '_';
    IF v_permissions IS NULL OR NOT (v_permissions ? '_') THEN
        RAISE EXCEPTION '_';
    END IF;

    
    IF p_0025 IS NULL OR p_0025 !~ '_' THEN
        RAISE EXCEPTION '_%_', COALESCE(p_0025, '_');
    END IF;

    
    IF p_0089 NOT IN ('_', '_') THEN
        RAISE EXCEPTION '_%_', p_0089;
    END IF;

    
    IF p_0054 NOT IN ('_', '_', '_') THEN
        RAISE EXCEPTION '_%_', p_0054;
    END IF;

    
    
    v_level := v_rbac_context -> '_' ->> 0;

    BEGIN
        v_user_enterprise_id := (v_rbac_context -> '_' ->> 0)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_user_enterprise_id := NULL;
    END;

    BEGIN
        v_user_supplier_id := (v_rbac_context -> '_' ->> 0)::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        v_user_supplier_id := NULL;
    END;

    
    SELECT f_0041 INTO v_inviter_email
    FROM auth.t_0095
    WHERE id = v_current_user_id;

    
    v_db_role := p_0054 || '_' || p_0089;

    
    IF p_0054 = '_' THEN
        IF p_0072 IS NOT NULL THEN
            v_enterprise_id := p_0072;
        ELSE
            v_enterprise_name := COALESCE(p_0028, '_' || p_0025);
        END IF;

    ELSIF p_0054 = '_' THEN
        IF v_user_enterprise_id IS NULL AND p_0072 IS NULL THEN
            RAISE EXCEPTION '_';
        END IF;

        v_enterprise_id := v_user_enterprise_id;

        IF v_level = '_' THEN
            v_supplier_name := COALESCE(p_0028, '_' || p_0025);
        ELSE
            v_supplier_id := p_0072;
        END IF;

    ELSIF p_0054 = '_' THEN
        IF v_level = '_' THEN
            
            
            IF p_0089 = '_' AND p_0072 IS NOT NULL THEN
                v_supplier_id := p_0072;
            END IF;
        ELSIF v_level = '_' THEN
            v_supplier_id := v_user_supplier_id;
        ELSIF v_level = '_' THEN
            IF v_rbac_context -> '_' ? '_' THEN
                v_supplier_id := v_user_supplier_id;
                IF v_supplier_id IS NULL AND v_user_enterprise_id IS NULL THEN
                    RAISE EXCEPTION '_';
                END IF;
            ELSE
                RAISE EXCEPTION '_';
            END IF;
        ELSE
            RAISE EXCEPTION '_';
        END IF;

        v_enterprise_id := v_user_enterprise_id;

        IF p_0089 = '_' THEN
            v_farmer_name := COALESCE(p_0028, '_' || p_0025);
        ELSE
            IF p_0072 IS NULL THEN
                RAISE EXCEPTION '_';
            END IF;
            IF v_supplier_id IS NOT NULL THEN
                IF NOT EXISTS (
                    SELECT 1 FROM public.t_0091
                    WHERE p_0005 = p_0072 AND p_0122 = v_supplier_id
                ) THEN
                    RAISE EXCEPTION '_';
                END IF;
            ELSE
                IF NOT EXISTS (
                    SELECT 1 FROM public.t_0049
                    WHERE p_0005 = p_0072 AND p_0001 = v_enterprise_id
                    UNION ALL
                    SELECT 1 FROM public.t_0091 sf
                    JOIN public.t_0050 es ON es.p_0122 = sf.p_0122
                    WHERE sf.p_0005 = p_0072 AND es.p_0001 = v_enterprise_id
                ) THEN
                    RAISE EXCEPTION '_';
                END IF;
            END IF;
            v_farmer_id := p_0072;
        END IF;
    END IF;

    RETURN QUERY SELECT
        p_0025,
        p_0089,
        p_0054,
        v_db_role,
        v_current_user_id,
        v_enterprise_id,
        v_enterprise_name,
        v_supplier_id,
        v_supplier_name,
        v_farmer_id,
        v_farmer_name,
        p_0028,
        v_level,
        v_inviter_email;
END;
$$;









CREATE OR REPLACE FUNCTION mrv.f_0129(
    p_0078 uuid,
    p_0023 jsonb,
    p_0104 boolean DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_existing_id uuid;
    v_existing_submitted_at timestamptz;
    v_row RECORD;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0111(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0033" p WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    
    
    
    SELECT "id", "c_0483"
    INTO v_existing_id, v_existing_submitted_at
    FROM mrv."t_0034"
    WHERE "c_0369" = p_0078
    FOR UPDATE;

    IF v_existing_submitted_at IS NOT NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF v_existing_id IS NULL THEN
        INSERT INTO mrv."t_0034" (
            "c_0369",
            "c_0398",
            "c_0399",
            "c_0397",
            "c_0038",
            "c_0040",
            "c_0039",
            "c_0074",
            "c_0072",
            "c_0076",
            "c_0075",
            "c_0073",
            "c_0483"
        )
        VALUES (
            p_0078,
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_')::mrv."ty_0023",
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_')::mrv."ty_0024",
            NULLIF(p_0023->>'_', '_')::numeric,
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_'),
            NULLIF(p_0023->>'_', '_'),
            CASE WHEN p_0104 THEN now() ELSE NULL END
        )
        RETURNING * INTO v_row;
    ELSE
        
        
        
        
        UPDATE mrv."t_0034"
        SET
            "c_0398"     = NULLIF(p_0023->>'_', '_'),
            "c_0399"        = NULLIF(p_0023->>'_', '_'),
            "c_0397"      = NULLIF(p_0023->>'_', '_'),
            "c_0038"                   = NULLIF(p_0023->>'_', '_')::mrv."ty_0023",
            "c_0040"                  = NULLIF(p_0023->>'_', '_'),
            "c_0039"                = NULLIF(p_0023->>'_', '_'),
            "c_0074"              = NULLIF(p_0023->>'_', '_')::mrv."ty_0024",
            "c_0072"     = NULLIF(p_0023->>'_', '_')::numeric,
            "c_0076"  = NULLIF(p_0023->>'_', '_'),
            "c_0075"           = NULLIF(p_0023->>'_', '_'),
            "c_0073"         = NULLIF(p_0023->>'_', '_'),
            "c_0483"                       = CASE WHEN p_0104 THEN now() ELSE "c_0483" END,
            "c_0528"                         = now()
        WHERE "id" = v_existing_id AND "c_0483" IS NULL
        RETURNING * INTO v_row;

        IF NOT FOUND THEN
            RAISE EXCEPTION '_';
        END IF;
    END IF;

    RETURN to_jsonb(v_row);
END;
$$;

COMMENT ON FUNCTION mrv.f_0129(uuid, jsonb, boolean) IS
    '_';




















CREATE OR REPLACE FUNCTION mrv.f_0130(
    p_0078 uuid,
    p_0035    uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_eligibility_boundary public.geometry;
    v_farm_polygon_id      uuid;
    v_farm_geometry        public.geometry;
    v_boundary_normalized  public.geometry;
    v_farm_normalized      public.geometry;
    v_matched_row_id       uuid;
    v_has_matrix_rows      boolean;
BEGIN
    
    SELECT "c_0147"
    INTO v_eligibility_boundary
    FROM mrv."t_0033"
    WHERE id = p_0078;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0078;
    END IF;

    
    
    SELECT "c_0355"
    INTO v_farm_polygon_id
    FROM mrv."t_0012"
    WHERE id = p_0035;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0035;
    END IF;

    
    
    
    
    IF v_eligibility_boundary IS NOT NULL THEN
        IF v_farm_polygon_id IS NULL THEN
            RETURN jsonb_build_object(
                '_',       false,
                '_',        '_',
                '_',  NULL
            );
        END IF;

        SELECT geometry
        INTO v_farm_geometry
        FROM mrv."Polygon"
        WHERE id = v_farm_polygon_id;

        IF NOT FOUND OR v_farm_geometry IS NULL THEN
            RETURN jsonb_build_object(
                '_',       false,
                '_',        '_',
                '_',  NULL
            );
        END IF;

        
        
        v_boundary_normalized := CASE WHEN ST_SRID(v_eligibility_boundary) = 0
            THEN ST_SetSRID(v_eligibility_boundary, 4326)
            ELSE ST_Transform(v_eligibility_boundary, 4326)
        END;
        v_farm_normalized := CASE WHEN ST_SRID(v_farm_geometry) = 0
            THEN ST_SetSRID(v_farm_geometry, 4326)
            ELSE ST_Transform(v_farm_geometry, 4326)
        END;

        IF NOT ST_Intersects(v_boundary_normalized, v_farm_normalized) THEN
            RETURN jsonb_build_object(
                '_',       false,
                '_',        '_',
                '_',  NULL
            );
        END IF;
    END IF;

    
    SELECT EXISTS (
        SELECT 1
        FROM mrv."t_0036"
        WHERE "c_0369" = p_0078
    ) INTO v_has_matrix_rows;

    IF NOT v_has_matrix_rows THEN
        RETURN jsonb_build_object(
            '_',       true,
            '_',        '_',
            '_',  NULL
        );
    END IF;

    
    
    
    
    
    
    
    
    SELECT id
    INTO v_matched_row_id
    FROM mrv."t_0036"
    WHERE "c_0369" = p_0078
    ORDER BY "c_0093"
    LIMIT 1;

    IF v_matched_row_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            '_',       true,
            '_',        '_',
            '_',  v_matched_row_id
        );
    END IF;

    RETURN jsonb_build_object(
        '_',       false,
        '_',        '_',
        '_',  NULL
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0131(
    p_0079 uuid,
    p_0070 text,
    p_0014 char(2)[],
    p_0117 text DEFAULT NULL,
    p_0024 jsonb DEFAULT 'null'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_project_id uuid;
    v_proponent_id uuid;
    v_eligibility_row jsonb;
    v_row_index integer;
    v_allowed_practices text[];
BEGIN
    IF NOT auth.f_0061() THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0079 IS NULL THEN
        SELECT id INTO v_proponent_id
        FROM mrv."t_0024"
        WHERE "c_0258" = true;

        IF v_proponent_id IS NULL THEN
            RAISE EXCEPTION '_';
        END IF;
    ELSE
        v_proponent_id := p_0079;

        IF NOT EXISTS (SELECT 1 FROM mrv."t_0024" WHERE id = v_proponent_id) THEN
            RAISE EXCEPTION '_%_', v_proponent_id;
        END IF;
    END IF;

    INSERT INTO mrv."t_0033" (
        "c_0375",
        "name",
        "c_0087",
        "c_0538",
        "c_0472"
    )
    VALUES (
        v_proponent_id,
        p_0070,
        p_0014,
        p_0117,
        '_'
    )
    RETURNING "id" INTO v_project_id;

    INSERT INTO mrv."t_0035" ("c_0369", "c_0357", "c_0257")
    SELECT v_project_id, pool_type, true
    FROM unnest(ARRAY[
        '_',
        '_',
        '_',
        '_',
        '_',
        '_'
    ]::mrv."ty_0025"[]) AS pool_type;

    IF p_0024 IS NOT NULL AND jsonb_array_length(p_0024) > 0 THEN
        v_row_index := 0;
        FOR v_eligibility_row IN SELECT * FROM jsonb_array_elements(p_0024)
        LOOP
            IF (v_eligibility_row->>'_') IS NULL
                OR (v_eligibility_row->>'_') IS NULL
                OR (v_eligibility_row->>'_') IS NULL
                OR (v_eligibility_row->>'_') IS NULL
                OR (v_eligibility_row->>'_') IS NULL
            THEN
                RAISE EXCEPTION '_%_', v_row_index;
            END IF;

            SELECT ARRAY(
                SELECT jsonb_array_elements_text(v_eligibility_row->'_')
            ) INTO v_allowed_practices;

            INSERT INTO mrv."t_0036" (
                "c_0369",
                "c_0089",
                "c_0066",
                "c_0451",
                "c_0358",
                "c_0108",
                "c_0009"
            )
            VALUES (
                v_project_id,
                v_eligibility_row->>'_',
                v_eligibility_row->>'_',
                v_eligibility_row->>'_',
                v_eligibility_row->>'_',
                v_eligibility_row->>'_',
                COALESCE(v_allowed_practices, '{}'::text[])
            );

            v_row_index := v_row_index + 1;
        END LOOP;
    END IF;

    RETURN mrv.f_0138(v_project_id);
END;
$$;

COMMENT ON FUNCTION mrv.f_0131(uuid, text, char(2)[], text, jsonb) IS E'_';







CREATE OR REPLACE FUNCTION mrv.f_0132(
    p_0105 uuid,
    p_0070 text,
    p_0014 char(2)[]
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_project_id    uuid;
    v_proponent_id  uuid;
    v_rbac_context  jsonb;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
