        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0061() THEN
        v_rbac_context := auth.f_0066()->'_';
        IF v_rbac_context IS NULL
           OR NOT (v_rbac_context->'_' ? p_0105::text)
        THEN
