CREATE OR REPLACE FUNCTION mrv.f_0134(
    p_0078    uuid,
    p_0053 text,
    p_0105   uuid,
    p_0015  text
)
RETURNS TABLE (
    id            uuid,
    "c_0369"   uuid,
    "c_0237" text,
