    "c_0093"   timestamptz,
    "c_0528"   timestamptz
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_proponent_id  uuid;
    v_status        text := '_';
BEGIN
    SELECT "c_0375"
    INTO v_proponent_id
    FROM mrv."t_0033"
    WHERE id = p_0078;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0078;
    END IF;

    IF NOT auth.f_0122(v_proponent_id) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0053 NOT IN ('_', '_', '_') THEN
        RAISE EXCEPTION '_%_', p_0053;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM mrv."t_0036"
        WHERE "c_0369" = p_0078
          AND "c_0089" = p_0015
    ) THEN
        v_status := '_';
    END IF;

    RETURN QUERY
    INSERT INTO mrv."t_0038" (
        "c_0369",
        "c_0237",
        "c_0472",
        "c_0486",
        "c_0089"
    )
    VALUES (
        p_0078,
        p_0053::mrv."ty_0027",
        v_status::mrv."ty_0026",
        p_0105,
        p_0015
    )
    RETURNING
        "t_0038".id,
        "t_0038"."c_0369",
        "t_0038"."c_0237"::text,
        "t_0038".c_0472::text,
        "t_0038"."c_0089",
        "t_0038"."c_0486",
        "t_0038"."c_0093",
        "t_0038"."c_0528";
END;
$$;








CREATE OR REPLACE FUNCTION mrv.f_0135(
    p_0078 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0033" p
        WHERE p."id" = p_0078
    ) THEN
        RETURN NULL;
    END IF;

    IF NOT auth.f_0111(p_0078) THEN
        RAISE EXCEPTION '_';
