CREATE OR REPLACE FUNCTION mrv.f_0136()
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    RETURN COALESCE(
        (
            SELECT jsonb_agg(mrv.f_0138(p."id") ORDER BY p."c_0093" DESC)
            FROM mrv."t_0033" p
            WHERE auth.f_0111(p."id")
        ),
        'null'::jsonb
    );
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0137(
    p_0078 uuid,
    p_0035 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0111(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0033" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    DELETE FROM mrv."t_0037"
    WHERE "c_0369" = p_0078
      AND "c_0187" = p_0035;

    UPDATE mrv."t_0033"
    SET "c_0528" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0138(p_0078);
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0138(
    p_0078 uuid
)
RETURNS JSONB
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        '_', p."id",
        '_', p."name",
        '_', p."c_0140",
        '_', p."c_0472"::text,
        '_', to_char(p."c_0098", '_'),
        '_', to_char(p."c_0097", '_'),
        '_', p."c_0368",
        '_', p."c_0042",
        '_', p."c_0005",
        '_', p."c_0289",
        '_', p."c_0318",
        '_', p."c_0343",
        '_', p."c_0093",
        '_', p."c_0528",
        '_', COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        '_', cp."id",
                        '_', cp."c_0357"::text,
                        '_', cp."c_0257",
                        '_', cp."c_0180"
                    )
                    ORDER BY cp."c_0357"::text
                )
                FROM mrv."t_0035" cp
                WHERE cp."c_0369" = p."id"
            ),
            'null'::jsonb
        ),
        '_', COALESCE(
            (
                SELECT jsonb_agg(
                    jsonb_build_object(
                        '_', pf."id",
                        '_', pf."c_0187",
                        '_', f."name",
                        '_', pf."c_0478"
                    )
                    ORDER BY f."name"
                )
                FROM mrv."t_0037" pf
                JOIN mrv."t_0012" f ON f."id" = pf."c_0187"
                WHERE pf."c_0369" = p."id"
            ),
            'null'::jsonb
        )
    )
    INTO v_result
    FROM mrv."t_0033" p
    WHERE p."id" = p_0078;

    RETURN v_result;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0139(
    p_0078 uuid,
    p_0112 jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_status_value text;
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0111(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0033" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0112 ? '_' AND p_0112->>'_' IS NOT NULL THEN
        v_status_value := p_0112->>'_';
        IF v_status_value NOT IN ('_', '_', '_', '_') THEN
            RAISE EXCEPTION '_%_', v_status_value;
        END IF;
    END IF;

    UPDATE mrv."t_0033"
    SET
        "name" = CASE WHEN p_0112 ? '_' THEN p_0112->>'_' ELSE "name" END,
        "c_0140" = CASE WHEN p_0112 ? '_' THEN p_0112->>'_' ELSE "c_0140" END,
        "c_0472" = CASE WHEN p_0112 ? '_' AND p_0112->>'_' IS NOT NULL
                        THEN (p_0112->>'_')::mrv."ty_0029"
                        ELSE "c_0472" END,
        "c_0098" = CASE WHEN p_0112 ? '_'
                                      THEN (p_0112->>'_')::date
                                      ELSE "c_0098" END,
        "c_0097" = CASE WHEN p_0112 ? '_'
                                    THEN (p_0112->>'_')::date
                                    ELSE "c_0097" END,
        "c_0368" = CASE WHEN p_0112 ? '_'
                                            THEN p_0112->>'_'
                                            ELSE "c_0368" END,
        "c_0042" = CASE WHEN p_0112 ? '_'
                                             THEN p_0112->>'_'
                                             ELSE "c_0042" END,
        "c_0005" = CASE WHEN p_0112 ? '_'
                                            THEN p_0112->>'_'
                                            ELSE "c_0005" END,
        "c_0289" = CASE WHEN p_0112 ? '_'
                                       THEN p_0112->>'_'
                                       ELSE "c_0289" END,
        "c_0318" = CASE WHEN p_0112 ? '_'
                                           THEN p_0112->>'_'
                                           ELSE "c_0318" END,
        "c_0343" = CASE WHEN p_0112 ? '_'
                                         THEN (p_0112->>'_')::numeric
                                         ELSE "c_0343" END,
        "c_0528" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0138(p_0078);
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0140(
    p_0078 uuid,
    p_0075 jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = mrv, auth, public
AS $$
DECLARE
    v_pool jsonb;
    v_pool_type text;
    v_is_included boolean;
    v_justification text;
    v_all_pool_types mrv."ty_0025"[] := ARRAY[
        '_',
        '_',
        '_',
        '_',
        '_',
        '_'
    ]::mrv."ty_0025"[];
    v_provided_types text[];
BEGIN
    IF auth.f_0102() IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0111(p_0078) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mrv."t_0033" p
        WHERE p."id" = p_0078
    ) THEN
        RAISE EXCEPTION '_';
    END IF;

    SELECT array_agg(pool->>'_')
    INTO v_provided_types
    FROM jsonb_array_elements(p_0075) AS pool;

    IF (
        SELECT count(*)
        FROM unnest(v_all_pool_types) AS required_type
        WHERE required_type::text != ALL(COALESCE(v_provided_types, ARRAY[]::text[]))
    ) > 0 THEN
        RAISE EXCEPTION '_';
    END IF;

    FOR v_pool IN SELECT * FROM jsonb_array_elements(p_0075)
    LOOP
        v_pool_type := v_pool->>'_';
        v_is_included := (v_pool->>'_')::boolean;
        v_justification := v_pool->>'_';

        IF v_pool_type = '_' AND NOT v_is_included THEN
            RAISE EXCEPTION '_';
        END IF;

        IF NOT v_is_included AND v_justification IS NULL THEN
            RAISE EXCEPTION '_%_', v_pool_type;
        END IF;
    END LOOP;

    DELETE FROM mrv."t_0035"
    WHERE "c_0369" = p_0078;

    INSERT INTO mrv."t_0035" (
        "c_0369",
        "c_0357",
        "c_0257",
        "c_0180"
    )
    SELECT
        p_0078,
        (pool->>'_')::mrv."ty_0025",
        (pool->>'_')::boolean,
        pool->>'_'
    FROM jsonb_array_elements(p_0075) AS pool;

    UPDATE mrv."t_0033"
    SET "c_0528" = now()
    WHERE "id" = p_0078;

    RETURN mrv.f_0138(p_0078);
END;
$$;


CREATE OR REPLACE FUNCTION mrv.f_0141(
    p_0026 uuid,
    p_0012 int
)
RETURNS TABLE (
    p_0004 uuid,
    c_0191 text,
    c_0090 text,
    c_0429 text,
    c_0279 text,
    c_0162 double precision,
    c_0165 double precision,
    c_0163 double precision,
    c_0164 double precision,
    c_0113 double precision,
    c_0116 double precision,
    c_0114 double precision,
    c_0115 double precision,
    c_0322 double precision,
    c_0519 double precision,
    c_0161 text,
    c_0053 timestamptz,
    c_0056 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
BEGIN
    RETURN QUERY
    SELECT
        f.id AS p_0004,
        f.name AS c_0191,
        f."ty_0003"::text AS c_0090,
        f."ty_0016"::text AS c_0429,
        f."ty_0013"::text AS c_0279,
        d."c_0157" AS c_0162,
        d."c_0160" AS c_0165,
        d."c_0158" AS c_0163,
        d."c_0159" AS c_0164,
        d."c_0109" AS c_0113,
        d."c_0112" AS c_0116,
        d."c_0110" AS c_0114,
        d."c_0111" AS c_0115,
        d."c_0321" AS c_0322,
        d."c_0511" AS c_0519,
        d."c_0156"::text AS c_0161,
        d."c_0052" AS c_0053,
        d."c_0055" AS c_0056
    FROM mrv."t_0012" f
    JOIN mrv."t_0007" d
        ON d."c_0187" = f.id
        AND d."c_0057" = p_0012
    WHERE f."c_0172" IN (
        SELECT ur.p_0124
        FROM public.t_0094 ur
        JOIN public.t_0091 sf ON sf.p_0005 = ur.p_0005
        JOIN public.t_0050 es ON es.p_0122 = sf.p_0122
        WHERE es.p_0001 = p_0026
    )
    ORDER BY f.name;
END;
$$;




CREATE OR REPLACE FUNCTION mrv.f_0144(
    p_0052 uuid
)
RETURNS TABLE (
    c_0439 text,
    c_0129 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY INVOKER
AS $$
DECLARE
    v_supplier_id uuid;
BEGIN
    SELECT vpi."c_0486"
    INTO v_supplier_id
    FROM mrv."t_0038" vpi
    WHERE vpi.id = p_0052;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', vp.id,
                        '_', vp.name,
                        '_', vp.c_0140,
                        '_', vp.c_0472,
                        '_', vp."c_0098",
                        '_', vp."c_0097",
                        '_', jsonb_build_object(
                            '_', vp."c_0368",
                            '_', vp."c_0042",
                            '_', vp."c_0005",
                            '_', vp."c_0289",
                            '_', vp."c_0318",
                            '_', vp."c_0343"
                        ),
                        '_', (
                            SELECT COALESCE(jsonb_agg(
                                jsonb_build_object(
                                    '_', cp."c_0357",
                                    '_', cp."c_0257",
                                    '_', cp."c_0180"
                                )
                            ), 'null'::jsonb)
                            FROM mrv."t_0035" cp
                            WHERE cp."c_0369" = vp.id
                        ),
                        '_', (
                            SELECT COALESCE(jsonb_agg(pf."c_0187"), 'null'::jsonb)
                            FROM mrv."t_0037" pf
                            WHERE pf."c_0369" = vp.id
                              AND pf."c_0236" = p_0052
                        )
                    )
                ), 'null'::jsonb)
            )
            FROM mrv."t_0033" vp
            WHERE vp.id IN (
                SELECT DISTINCT pf2."c_0369"
                FROM mrv."t_0037" pf2
                WHERE pf2."c_0236" = p_0052
            )
        ) AS c_0129;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', f.id,
                        '_', f.name,
                        '_', f."ty_0003",
                        '_', f."ty_0016",
                        '_', f."ty_0013",
                        '_', CASE
                            WHEN p.geometry IS NOT NULL
                            THEN ST_AsGeoJSON(p.geometry)::jsonb
                        END,
                        '_', (
                            SELECT pf."c_0478"
                            FROM mrv."t_0037" pf
                            WHERE pf."c_0187" = f.id
                              AND pf."c_0236" = p_0052
                            ORDER BY pf."c_0369"
                            LIMIT 1
                        )
                    )
                    ORDER BY f.id
                ), 'null'::jsonb)
            )
            FROM mrv."t_0012" f
            LEFT JOIN mrv."Polygon" p ON p.id = f."c_0355"
            WHERE f.id IN (
                SELECT pf."c_0187"
                FROM mrv."t_0037" pf
                WHERE pf."c_0236" = p_0052
            )
        ) AS c_0129;

    
    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', cp.id,
                        '_', cp.c_0472,
                        '_', cp."c_0218",
                        '_', cp."c_0494",
                        '_', cp."c_0495",
                        '_', cp."c_0121",
                        '_', cp."c_0122",
                        '_', cp."c_0209",
                        '_', cp.c_0413,
                        '_', (
                            SELECT COALESCE(jsonb_agg(cpf."c_0187"), 'null'::jsonb)
                            FROM mrv."t_0002" cpf
                            WHERE cpf."c_0058" = cp.id
                        ),
                        '_', cp."c_0093"
                    )
                ), 'null'::jsonb)
            )
            FROM mrv."t_0001" cp
            WHERE cp."c_0172" = v_supplier_id
              AND cp.c_0472 = 'v1'
        ) AS c_0129;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', d."c_0187",
                        '_', d."c_0057",
                        '_', d."c_0321",
                        '_', d."c_0511",
                        '_', d."c_0157",
                        '_', d."c_0160",
                        '_', d."c_0158",
                        '_', d."c_0159",
                        '_', d."c_0109",
                        '_', d."c_0112",
                        '_', d."c_0110",
                        '_', d."c_0111",
                        '_', d."c_0156",
                        '_', d."c_0052"
                    )
                    ORDER BY d."c_0187", d."c_0057"
                ), 'null'::jsonb),
                '_', (
                    SELECT COALESCE(jsonb_agg(
                        jsonb_build_object(
                            '_', sub."c_0187",
                            '_', sub.total_net,
                            '_', sub.latest_carbon,
                            '_', sub.year_count,
                            '_', sub.first_year,
                            '_', sub.last_year
                        )
                    ), 'null'::jsonb)
                    FROM (
                        SELECT
                            d2."c_0187",
                            SUM(d2."c_0321") AS total_net,
                            (ARRAY_AGG(d2."c_0511" ORDER BY d2."c_0057" DESC))[1] AS latest_carbon,
                            COUNT(*) AS year_count,
                            MIN(d2."c_0057") AS first_year,
                            MAX(d2."c_0057") AS last_year
                        FROM mrv."t_0007" d2
                        WHERE d2."c_0187" IN (
                            SELECT pf."c_0187"
                            FROM mrv."t_0037" pf
                            WHERE pf."c_0236" = p_0052
                        )
                        GROUP BY d2."c_0187"
                    ) sub
                )
            )
            FROM mrv."t_0007" d
            WHERE d."c_0187" IN (
                SELECT pf."c_0187"
                FROM mrv."t_0037" pf
                WHERE pf."c_0236" = p_0052
            )
        ) AS c_0129;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', c.id,
                        '_', c."c_0187",
                        '_', c."c_0102",
                        '_', c."c_0351",
                        '_', c."c_0222",
                        '_', c."c_0250",
                        '_', c."c_0501",
                        '_', c.c_0472,
                        '_', jsonb_build_object(
                            '_', s.id,
                            '_', s.name,
                            '_', s."c_0470",
                            '_', s."c_0168"
                        )
                    )
                    ORDER BY c."c_0187", c."c_0351"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0006" c
            JOIN mrv."t_0025" s ON s.id = c."c_0436"
            WHERE c."c_0187" IN (
                SELECT pf."c_0187"
                FROM mrv."t_0037" pf
                WHERE pf."c_0236" = p_0052
            )
        ) AS c_0129;

    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', sr.id,
                        '_', sr."c_0187",
                        '_', sr."c_0422",
                        '_', (
                            SELECT COALESCE(jsonb_agg(
                                jsonb_build_object(
                                    '_', sm.c_0339,
                                    '_', sm.value
                                )
                            ), 'null'::jsonb)
                            FROM mrv."t_0026" sm
                            WHERE sm."c_0452" = sr.id
                        )
                    )
                    ORDER BY sr."c_0187", sr."c_0422"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0027" sr
            WHERE sr."c_0187" IN (
                SELECT pf."c_0187"
                FROM mrv."t_0037" pf
                WHERE pf."c_0236" = p_0052
            )
        ) AS c_0129;

    
    
    RETURN QUERY
    SELECT
        '_'::text AS c_0439,
        (
            SELECT jsonb_build_object(
                '_', COALESCE(jsonb_agg(
                    jsonb_build_object(
                        '_', s.id,
                        '_', s.name,
                        '_', s."c_0470",
                        '_', s."c_0168"
                    )
                    ORDER BY s."c_0470"
                ), 'null'::jsonb)
            )
            FROM mrv."t_0025" s
            WHERE s."c_0172" = v_supplier_id
        ) AS c_0129;
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0145(
    p_0050 uuid
)
RETURNS TABLE(id uuid, "c_0486" uuid, "c_0170" uuid, "c_0455" text, "c_0458" uuid, "c_0102" text, "c_0381" double precision, "c_0489" date, "c_0094" uuid, "c_0093" timestamptz, "c_0528" timestamptz)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
    v_existing RECORD;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtext('_' || p_0050::text));

    SELECT *
    INTO v_existing
    FROM mrv."t_0028"
    WHERE id = p_0050;

    IF v_existing IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0105 => v_existing."c_0486") THEN
        RAISE EXCEPTION '_';
    END IF;

    DELETE FROM mrv."t_0028" WHERE id = p_0050;

    IF NOT FOUND THEN
        RAISE EXCEPTION '_%_', p_0050;
    END IF;

    RETURN QUERY SELECT
        v_existing.id,
        v_existing."c_0486",
        v_existing."c_0170",
        v_existing."c_0455"::text,
        v_existing."c_0458",
        v_existing."c_0102"::text,
        v_existing."c_0381",
        v_existing."c_0489",
        v_existing."c_0094",
        v_existing."c_0093",
        v_existing."c_0528";
END;
$$;

CREATE OR REPLACE FUNCTION mrv.f_0146(
    p_0026 uuid,
    p_0118 int
)
RETURNS TABLE (
    c_0032 numeric,
    c_0312 numeric,
    c_0306 numeric,
    c_0473 numeric,
    c_0051 jsonb,
    c_0049 jsonb,
    c_0523 jsonb
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER 
SET search_path = mrv, auth, public
AS $$
#variable_conflict use_column
DECLARE
    v_current_user_id uuid;
BEGIN
    v_current_user_id := auth.f_0102();
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF NOT auth.f_0119(p_0026 => p_0026) THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0118 IS NULL THEN
        RAISE EXCEPTION '_';
    END IF;

    IF p_0118 < 2000 OR p_0118 > EXTRACT(YEAR FROM NOW())::int + 5 THEN
        RAISE EXCEPTION '_%_', p_0118;
    END IF;

    RETURN QUERY
    WITH t_0050 AS (
        SELECT s.id AS p_0122, s.name AS c_0488
        FROM public.t_0050 es
        JOIN public.t_0092 s ON s.id = es.p_0122
        WHERE es.p_0001 = p_0026
    ),
    enterprise_farms AS (
        SELECT farm.id AS p_0004, farm."c_0172" AS con_0122, p.geometry,
               ST_Area(p.geometry::geography) / 10000 AS c_0018
        FROM mrv."t_0012" farm
        JOIN mrv."Polygon" p ON p.id = farm."c_0355"
        WHERE farm."c_0172" IN (SELECT p_0122 FROM t_0050)
        UNION
        
        SELECT farm.id, farm."c_0172", p.geometry,
               ST_Area(p.geometry::geography) / 10000
        FROM mrv."t_0012" farm
        JOIN mrv."Polygon" p ON p.id = farm."c_0355"
        JOIN public.t_0091 sf ON sf.p_0005 = farm."c_0172"
        JOIN t_0050 es ON es.p_0122 = sf.p_0122
    ),
    farm_supplier_mapping AS (
        SELECT ef.p_0004, ef.con_0122 AS p_0122
        FROM enterprise_farms ef
        WHERE ef.con_0122 IN (SELECT p_0122 FROM t_0050)
        UNION
        SELECT ef.p_0004, sf.p_0122
        FROM enterprise_farms ef
        JOIN public.t_0091 sf ON sf.p_0005 = ef.con_0122
    ),
    harvest_data AS (
        SELECT
            hr."c_0512",
            c."c_0102"::text AS c_0105,
            ef.p_0004,
            ef.con_0122,
            ef.c_0018
        FROM mrv."t_0016" hr
        JOIN mrv."t_0006" c ON c.id = hr."c_0117"
        JOIN enterprise_farms ef ON ef.p_0004 = c."c_0187"
        WHERE c.c_0472 = 'v1'
            AND c."c_0222" >= make_date(p_0118, 1, 1)
            AND c."c_0222" < make_date(p_0118 + 1, 1, 1)
            AND hr."c_0512" IS NOT NULL
            AND hr."c_0512" > 0
            AND ef.c_0018 > 0
    ),
    yield_per_ha_data AS (
        SELECT
            p_0004,
            con_0122,
            c_0105,
            "c_0512",
            c_0018,
            ("c_0512" / c_0018) AS yield_per_ha
        FROM harvest_data
    ),
    overall_stats AS (
        SELECT
            AVG(yield_per_ha)::numeric    AS c_0032,
            MIN(yield_per_ha)::numeric    AS c_0312,
            MAX(yield_per_ha)::numeric    AS c_0306,
            STDDEV(yield_per_ha)::numeric AS c_0473
        FROM yield_per_ha_data
    ),
    by_supplier_agg AS (
        SELECT
            es.p_0122,
            es.c_0488,
            AVG(yphd.yield_per_ha)::numeric AS c_0032,
            COUNT(DISTINCT fsm.p_0004) AS c_0189
        FROM t_0050 es
        JOIN farm_supplier_mapping fsm ON fsm.p_0122 = es.p_0122
        JOIN yield_per_ha_data yphd ON yphd.p_0004 = fsm.p_0004
        GROUP BY es.p_0122, es.c_0488
    ),
    by_supplier_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', p_0122,
                '_', c_0488,
                '_', c_0032,
                '_', c_0189
            )
        ), 'null'::jsonb) AS c_0411
        FROM by_supplier_agg
    ),
    crop_area AS (
        SELECT c_0105, SUM(c_0018)::numeric AS c_0018
        FROM (SELECT DISTINCT c_0105, p_0004, c_0018 FROM yield_per_ha_data) deduped
        GROUP BY c_0105
    ),
    by_crop_agg AS (
        SELECT
            yphd.c_0105,
            AVG(yphd.yield_per_ha)::numeric AS c_0032,
            SUM(yphd."c_0512")::numeric AS c_0521,
            ca.c_0018
        FROM yield_per_ha_data yphd
        JOIN crop_area ca ON ca.c_0105 = yphd.c_0105
        GROUP BY yphd.c_0105, ca.c_0018
    ),
    by_crop_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', c_0105,
                '_', c_0032,
                '_', c_0521,
                '_', c_0018
            )
        ), 'null'::jsonb) AS c_0411
        FROM by_crop_agg
    ),
    trend_years AS (
        SELECT generate_series(p_0118 - 4, p_0118) AS yr
    ),
    trend_data AS (
        SELECT
            ty.yr,
            AVG(
                CASE
                    WHEN hr_trend."c_0512" IS NOT NULL
                         AND hr_trend."c_0512" > 0
                         AND ef_trend.c_0018 > 0
                    THEN hr_trend."c_0512" / ef_trend.c_0018
                    ELSE NULL
                END
            )::numeric AS c_0032
        FROM trend_years ty
        LEFT JOIN mrv."t_0006" c_trend ON
            c_trend.c_0472 = 'v1'
            AND c_trend."c_0222" >= make_date(ty.yr, 1, 1)
            AND c_trend."c_0222" < make_date(ty.yr + 1, 1, 1)
            AND c_trend."c_0187" IN (SELECT p_0004 FROM enterprise_farms)
        LEFT JOIN mrv."t_0016" hr_trend ON hr_trend."c_0117" = c_trend.id
        LEFT JOIN enterprise_farms ef_trend ON ef_trend.p_0004 = c_trend."c_0187"
        GROUP BY ty.yr
        ORDER BY ty.yr
    ),
    trend_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                '_', yr,
                '_', c_0032
            )
            ORDER BY yr
        ), 'null'::jsonb) AS c_0411
        FROM trend_data
    )
    SELECT
        os.c_0032,
        os.c_0312,
        os.c_0306,
        os.c_0473,
        bsj.c_0411 AS c_0051,
        bcj.c_0411 AS c_0049,
        tj.c_0411  AS c_0523
    FROM overall_stats os
    CROSS JOIN by_supplier_json bsj
    CROSS JOIN by_crop_json bcj
    CROSS JOIN trend_json tj;
END;
$$;




