CREATE OR REPLACE FUNCTION mrv.f_0018()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.c_0472 IS DISTINCT FROM NEW.c_0472 THEN
    PERFORM pg_notify(
      '_',
      json_build_object('_', json_build_array('_', NEW.id))::text
    );
  END IF;
  RETURN NEW;
END;
$$;

